// Test direct payment integration with Stripe-like API
async function testDirectPaymentIntegration() {
  // 1. Create payment intent
  const paymentIntent = await stripe.paymentIntents.create({
    amount: 5000, // $50.00
    currency: 'usd',
    payment_method_types: ['card'],
    metadata: {
      order_id: 'ORD-12345',
      test_case: 'valid_visa_card'
    }
  });

  // 2. Confirm payment with test card
  const result = await stripe.paymentIntents.confirm(
    paymentIntent.id,
    {
      payment_method: 'pm_card_visa', // Stripe test card
      return_url: 'https://shop.example.com/thank-you'
    }
  );

  // 3. Verify payment status
  console.assert(result.status === 'succeeded', 
    'Payment should succeed with valid test card');

  // 4. Verify webhook received
  const webhookEvent = await waitForWebhook('payment_intent.succeeded');
  console.assert(webhookEvent.data.object.id === paymentIntent.id,
    'Webhook should match payment intent');
}

// Test error scenarios
