  // Insufficient funds test card
  try {
    await stripe.paymentIntents.confirm(
      paymentIntent.id,
      { payment_method: 'pm_card_insufficientFunds' }
    );
  } catch (error) {
    console.assert(error.code === 'card_declined',
      'Should decline for insufficient funds');
  }
}

