public class PaymentErrorTest {

    @Test
    public void testCardDeclinedError() {
        // Arrange
        PaymentRequest request = new PaymentRequest()
            .amount(new BigDecimal("100.00"))
            .paymentMethodNonce("fake-valid-visa-nonce")
            .options()
                .submitForSettlement(true)
                .done();

        // Mock gateway to return declined response
        BraintreeGateway mockGateway = mock(BraintreeGateway.class);
        when(mockGateway.transaction()
            .sale(any(PaymentRequest.class)))
            .thenReturn(new Result<Transaction>(
                null,
                new ValidationError(
                    "transaction",
                    "processor_declined",
                    "2001: Declined"
                )
            ));

        // Act
        Result<Transaction> result = mockGateway.transaction().sale(request);

        // Assert
        assertFalse(result.isSuccess());
        assertEquals("processor_declined", 
            result.getErrors().getAllValidationErrors().get(0).getCode());

        // Verify error handling
        PaymentErrorHandler handler = new PaymentErrorHandler();
        String userMessage = handler.getUserFriendlyMessage(result);
        assertEquals("Your card was declined. Please use a different card.", 
            userMessage);
    }

    @Test
    public void testNetworkTimeoutRecovery() {
        // Test payment retry logic
        PaymentService service = new PaymentService();
        service.setMaxRetries(3);
        service.setRetryDelay(1000); // 1 second

        // Mock timeout on first two attempts
        PaymentGateway mockGateway = mock(PaymentGateway.class);
        when(mockGateway.processPayment(any()))
            .thenThrow(new NetworkTimeoutException())
            .thenThrow(new NetworkTimeoutException())
            .thenReturn(PaymentResult.success("TXN-123"));

        // Should succeed on third retry
        PaymentResult result = service.processWithRetry(
            new Payment(100.00, "USD"));

        assertTrue(result.isSuccess());
        assertEquals(3, service.getRetryCount());
    }
}

const crypto = require('crypto');

describe('Payment Webhook Handler', () => {

  test('should validate webhook signature', () => {
    const payload = JSON.stringify({
      id: 'evt_123',
      type: 'payment_intent.succeeded',
      data: { object: { id: 'pi_123', amount: 1000 } }
    });

    const secret = 'whsec_test_secret';
    const signature = crypto
      .createHmac('sha256', secret)
      .update(payload)
      .digest('hex');

    const headers = {
      'stripe-signature': `t=${Date.now()},v1=${signature}`
    };

    const isValid = validateWebhookSignature(payload, headers, secret);
    expect(isValid).toBe(true);
  });

  test('should handle duplicate webhooks', async () => {
    const webhookId = 'evt_dup_123';
    const payload = { id: webhookId, type: 'charge.succeeded' };

    // First webhook should be processed
    const result1 = await processWebhook(payload);
    expect(result1.processed).toBe(true);

    // Duplicate webhook should be ignored
    const result2 = await processWebhook(payload);
    expect(result2.processed).toBe(false);
    expect(result2.reason).toBe('duplicate_event');

    // Verify event tracking
    const event = await WebhookEvent.findOne({ eventId: webhookId });
    expect(event.processedCount).toBe(1);
  });

  test('should handle webhook processing failures', async () => {
    const payload = {
      id: 'evt_fail_123',
      type: 'payment_intent.payment_failed'
    };

    // Mock database failure
    jest.spyOn(Order, 'updateOne').mockRejectedValue(
      new Error('Database unavailable')
    );

    // Should retry with exponential backoff
    const result = await processWebhookWithRetry(payload, {
      maxRetries: 3,
      initialDelay: 1000
    });

    expect(result.retryCount).toBe(3);
    expect(result.status).toBe('failed');

    // Verify event marked for manual review
    const failedEvent = await FailedWebhook.findOne({
      eventId: 'evt_fail_123'
    });
    expect(failedEvent).toBeDefined();
  });
});

