import random
import json

class PaymentUser(HttpUser):
    wait_time = between(1, 3)

    def on_start(self):
        self.test_cards = [
            "4242424242424242",  # Visa
            "5555555555554444",  # Mastercard
            "378282246310005",   # Amex
        ]

    @task(3)
    def test_successful_payment(self):
        """Test successful payment flow"""
        # 1. Create order
        order_response = self.client.post("/api/orders", 
            json={"amount": random.randint(1000, 10000)}
        )
        order_id = order_response.json()["id"]

        # 2. Process payment
        card = random.choice(self.test_cards)
        payment_data = {
            "order_id": order_id,
            "card_number": card,
            "expiry": "12/28",
            "cvc": "123",
            "amount": order_response.json()["amount"]
        }

        with self.client.post("/api/payments/process", 
            json=payment_data,
            catch_response=True
        ) as response:
            if response.status_code == 200:
                response.success()
            else:
                response.failure(f"Payment failed: {response.text}")

    @task(1)
    def test_declined_payment(self):
        """Test declined card scenario"""
        payment_data = {
            "card_number": "4000000000000002",  # Always declined
            "expiry": "12/28",
            "cvc": "123",
            "amount": 5000
        }

        # Should return proper error
        self.client.post("/api/payments/process", 
            json=payment_data,
            name="/api/payments/process [declined]"
        )

    @task(2)
    def test_payment_status_check(self):
        """Test payment status polling"""
        self.client.get("/api/payments/status?order_id=test_123")

