// Test successful 3DS authentication
test('Successful 3DS Challenge', async t => {
  // Fill payment form
  await t
    .typeText('#card-number', '4000000000003220') // 3DS test card
    .typeText('#expiry', '12/28')
    .typeText('#cvc', '123')
    .click('#pay-now');

  // Wait for 3DS redirect
  await t.expect(Selector('.3ds-frame').visible).ok();

  // Simulate successful authentication
  await t
    .switchToIframe('.3ds-frame')
    .typeText('#password', '1234')
    .click('#authenticate')
    .switchToMainWindow();

  // Verify payment success
  await t.expect(Selector('.success-message').visible).ok();
  await t.expect(Selector('.success-message').innerText)
    .contains('Payment successful');
});

// Test failed 3DS authentication
test('Failed 3DS Challenge', async t => {
  await t
    .typeText('#card-number', '4000000000003063') // 3DS failure card
    .typeText('#expiry', '12/28')
    .typeText('#cvc', '123')
    .click('#pay-now');

  // Simulate failed authentication
  await t
    .switchToIframe('.3ds-frame')
    .click('#fail-authentication')
    .switchToMainWindow();

  // Verify proper error handling
  await t.expect(Selector('.error-message').visible).ok();
  await t.expect(Selector('.error-message').innerText)
    .contains('Authentication failed');

  // Verify card not charged
  const paymentStatus = await getPaymentStatus();
  await t.expect(paymentStatus).eql('canceled');
});

// Test frictionless flow (no challenge)
test('Frictionless 3DS Flow', async t => {
  await t
    .typeText('#card-number', '4000000000003055') // Frictionless test card
    .typeText('#expiry', '12/28')
    .typeText('#cvc', '123')
    .click('#pay-now');

  // Should complete without 3DS challenge
  await t.expect(Selector('.3ds-frame').exists).notOk();
  await t.expect(Selector('.success-message').visible).ok();
});

