import XCTest
@testable import YourApp

class LoginTests: XCTestCase {
    // Test lifecycle methods
    override func setUp() {
        super.setUp()
        // Initialize test environment
        print("Setting up iOS test environment")
    }

    override func tearDown() {
        // Clean up test resources
        super.tearDown()
    }

    // 3. Test Case Example
    func testLoginWithValidCredentials() {
        // Arrange
        let authService = AuthenticationService()
        let expectation = expectation(description: "Login completes")

        // Act
        authService.login(username: "test@example.com", 
                         password: "password123") { result in
            // Assert
            switch result {
            case .success(let user):
                XCTAssertNotNil(user.id, "User ID should not be nil")
                XCTAssertEqual(user.email, "test@example.com", 
                              "Email should match")
            case .failure(let error):
                XCTFail("Login should succeed: \(error.localizedDescription)")
            }
            expectation.fulfill()
        }

        // Wait for async operation
        wait(for: [expectation], timeout: 5.0)
    }

    // 4. UI Testing Example
    func testLoginUIFlow() {
        // Launch app
        let app = XCUIApplication()
        app.launch()

        // Interact with UI elements
        let emailField = app.textFields["emailField"]
        XCTAssertTrue(emailField.exists, "Email field should exist")
        emailField.tap()
        emailField.typeText("test@example.com")

        let passwordField = app.secureTextFields["passwordField"]
        passwordField.tap()
        passwordField.typeText("password123")

        // Tap login button
        app.buttons["loginButton"].tap()

        // Verify navigation
        XCTAssertTrue(app.staticTexts["Welcome"].waitForExistence(timeout: 5),
                     "Should navigate to welcome screen")
    }

    // 5. Performance Testing
    func testLoginPerformance() {
        measure {
            // Code to measure performance
            let authService = AuthenticationService()
            let expectation = self.expectation(description: "Performance test")

            authService.login(username: "test@example.com", 
                             password: "password123") { _ in
                expectation.fulfill()
            }

            wait(for: [expectation], timeout: 10)
        }
    }
}

