// Platform-Specific Permission Testing Example
// React Native implementation showing iOS/Android differences

import { Platform, Alert, Linking } from 'react-native';
import { check, request, PERMISSIONS, RESULTS } from 'react-native-permissions';

class PermissionManager {
  // iOS and Android have different permission models
  static getPlatformPermissions() {
    if (Platform.OS === 'ios') {
      return {
        camera: PERMISSIONS.IOS.CAMERA,
        photoLibrary: PERMISSIONS.IOS.PHOTO_LIBRARY,
        location: PERMISSIONS.IOS.LOCATION_WHEN_IN_USE,
        notifications: PERMISSIONS.IOS.NOTIFICATIONS,
        // iOS has one-time permissions for some features
        tracking: PERMISSIONS.IOS.APP_TRACKING_TRANSPARENCY,
      };
    } else {
      return {
        camera: PERMISSIONS.ANDROID.CAMERA,
        photoLibrary: PERMISSIONS.ANDROID.READ_EXTERNAL_STORAGE,
        location: PERMISSIONS.ANDROID.ACCESS_FINE_LOCATION,
        notifications: PERMISSIONS.ANDROID.POST_NOTIFICATIONS,
        // Android has background location as separate permission
        backgroundLocation: PERMISSIONS.ANDROID.ACCESS_BACKGROUND_LOCATION,
      };
    }
  }

  // Check permission status
  static async checkPermission(permissionType) {
    const permissions = this.getPlatformPermissions();
    const permission = permissions[permissionType];

    if (!permission) {
      console.error(`Permission ${permissionType} not available on ${Platform.OS}`);
      return RESULTS.UNAVAILABLE;
    }

    try {
      const result = await check(permission);
      console.log(`Permission ${permissionType} status: ${result}`);

      // Platform-specific handling
      switch (result) {
        case RESULTS.UNAVAILABLE:
          // This feature is not available (on this device / in this context)
          this.showFeatureUnavailableAlert(permissionType);
          break;

        case RESULTS.DENIED:
          // The permission has not been requested / is denied but requestable
          console.log('Permission denied but requestable');
          break;

        case RESULTS.LIMITED:
          // iOS 14+ - Photo library limited access
          console.log('Limited access granted (iOS 14+)');
          break;

        case RESULTS.GRANTED:
          console.log('Permission granted');
          break;

        case RESULTS.BLOCKED:
          // The permission is denied and not requestable anymore
          this.showSettingsAlert(permissionType);
          break;
      }

      return result;
    } catch (error) {
      console.error(`Error checking permission ${permissionType}:`, error);
      return RESULTS.DENIED;
    }
  }

  // Request permission with platform-specific flows
  static async requestPermission(permissionType, rationale = null) {
    const permissions = this.getPlatformPermissions();
    const permission = permissions[permissionType];

    if (!permission) {
      return RESULTS.UNAVAILABLE;
    }

    // Android: Show rationale if provided
    if (Platform.OS === 'android' && rationale) {
      const shouldShowRationale = await this.shouldShowRationale(permission);
      if (shouldShowRationale) {
        await this.showRationaleAlert(rationale);
      }
    }

    // iOS: Special handling for tracking permission
    if (permissionType === 'tracking' && Platform.OS === 'ios') {
      // iOS 14+ requires ATT framework for tracking
      return await this.requestTrackingPermission();
    }

    // Request the permission
    try {
      const result = await request(permission);
      console.log(`Permission ${permissionType} request result: ${result}`);

      // iOS: Handle provisional notification permission
      if (permissionType === 'notifications' && Platform.OS === 'ios') {
        if (result === RESULTS.GRANTED) {
          // Request full notification permission after provisional
          await this.requestFullNotificationPermission();
        }
      }

      return result;
    } catch (error) {
      console.error(`Error requesting permission ${permissionType}:`, error);
      return RESULTS.DENIED;
    }
  }

  // Platform-specific helper methods
  static async requestTrackingPermission() {
    // iOS App Tracking Transparency
    if (Platform.OS !== 'ios') {
      return RESULTS.UNAVAILABLE;
    }

    try {
      // Using react-native-tracking-transparency or similar
      const { requestTrackingPermission } = require('react-native-tracking-transparency');
      const status = await requestTrackingPermission();

      // Map to consistent results
      const resultMap = {
        'authorized': RESULTS.GRANTED,
        'denied': RESULTS.DENIED,
        'restricted': RESULTS.BLOCKED,
        'not-determined': RESULTS.DENIED,
      };

      return resultMap[status] || RESULTS.DENIED;
    } catch (error) {
      console.error('Error requesting tracking permission:', error);
      return RESULTS.DENIED;
    }
  }

  static showSettingsAlert(permissionType) {
    const platformMessages = {
      ios: {
        title: 'Permission Required',
        message: `Please enable ${permissionType} permission in Settings to use this feature.`,
        settingsLabel: 'Open Settings',
      },
      android: {
        title: 'Permission Denied',
        message: `To use this feature, please grant ${permissionType} permission in app settings.`,
        settingsLabel: 'App Settings',
      },
    };

    const messages = platformMessages[Platform.OS];

    Alert.alert(
      messages.title,
      messages.message,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: messages.settingsLabel,
          onPress: () => this.openAppSettings(),
        },
      ]
    );
  }

  static openAppSettings() {
    if (Platform.OS === 'ios') {
      Linking.openURL('app-settings:');
    } else {
      Linking.openSettings();
    }
  }

  // Test suite for permission flows
  static async runPermissionTests() {
    const testCases = [
      {
        name: 'Camera Permission',
        type: 'camera',
        rationale: 'We need camera access to take photos for your profile.',
      },
      {
        name: 'Location Permission',
        type: 'location',
        rationale: 'Location access helps us show nearby services.',
      },
      {
        name: 'Photo Library Access',
        type: 'photoLibrary',
        rationale: 'Access your photos to upload profile pictures.',
      },
    ];

    const results = [];

    for (const testCase of testCases) {
      console.log(`\n=== Testing: ${testCase.name} ===`);

      // Check current status
      const currentStatus = await this.checkPermission(testCase.type);

      // Request if needed
      let finalStatus = currentStatus;
      if (currentStatus === RESULTS.DENIED) {
        finalStatus = await this.requestPermission(testCase.type, testCase.rationale);
      }

      results.push({
        permission: testCase.name,
        platform: Platform.OS,
        initialStatus: currentStatus,
        finalStatus: finalStatus,
        passed: finalStatus === RESULTS.GRANTED || finalStatus === RESULTS.LIMITED,
      });
    }

    // Platform-specific additional tests
    if (Platform.OS === 'ios') {
      console.log('\n=== iOS-Specific: Tracking Permission ===');
      const trackingStatus = await this.requestTrackingPermission();
      results.push({
        permission: 'App Tracking Transparency',
        platform: 'ios',
        initialStatus: 'N/A',
        finalStatus: trackingStatus,
        passed: trackingStatus === RESULTS.GRANTED,
      });
    }

    if (Platform.OS === 'android') {
      console.log('\n=== Android-Specific: Background Location ===');
      const bgLocationStatus = await this.checkPermission('backgroundLocation');
      results.push({
        permission: 'Background Location',
        platform: 'android',
        initialStatus: bgLocationStatus,
        finalStatus: bgLocationStatus,
        passed: bgLocationStatus === RESULTS.GRANTED,
      });
    }

    return results;
  }
}

// Usage example
export async function testPlatformPermissions() {
  console.log(`Running permission tests on ${Platform.OS}...`);

  const results = await PermissionManager.runPermissionTests();

  console.log('\n=== Test Results ===');
  results.forEach(result => {
    console.log(`
${result.permission}:
  Platform: ${result.platform}
  Initial: ${result.initialStatus}
  Final: ${result.finalStatus}
  Passed: ${result.passed ? '✅' : '❌'}`);
  });

  const passedCount = results.filter(r => r.passed).length;
  console.log(`\nSummary: ${passedCount}/${results.length} permissions granted`);

  return results;
}

