                height: 915,
                pixelRatio: 2.625,
                userAgent: 'Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36',
                platform: 'Android'
            },
            {
                name: 'Samsung Galaxy S23 Ultra',
                width: 412,
                height: 878,
                pixelRatio: 3.5,
                userAgent: 'Mozilla/5.0 (Linux; Android 13; SM-S918B) AppleWebKit/537.36',
                platform: 'Android',
                hasSPen: true
            },
            {
                name: 'Samsung Galaxy Z Fold5 (Unfolded)',
                width: 712,
                height: 1000,
                pixelRatio: 3.5,
                userAgent: 'Mozilla/5.0 (Linux; Android 13; SM-F946B) AppleWebKit/537.36',
                platform: 'Android',
                isFoldable: true
            }
        ];

        this.testCases = [
            {
                name: 'Navigation Visibility',
                selector: '.main-navigation',
                assertions: ['isDisplayed', 'isClickable'],
                orientations: ['portrait', 'landscape']
            },
            {
                name: 'Content Layout',
                selector: '.content-container',
                assertions: ['isWithinViewport', 'hasCorrectWidth'],
                orientations: ['portrait']
            },
            {
                name: 'Form Elements',
                selector: 'input, select, textarea',
                assertions: ['isDisplayed', 'isEnabled', 'hasAdequateSize'],
                orientations: ['portrait', 'landscape']
            },
            {
                name: 'Touch Targets',
                selector: 'button, a[href], .clickable',
                assertions: ['hasMinimumSize'],  // 44x44 points minimum
                orientations: ['portrait']
            }
        ];
    }

    async runResponsiveTests(baseUrl) {
        const results = {};

        for (const device of this.testDevices) {
            console.log(`Testing on ${device.name}...`);

            results[device.name] = {
                deviceInfo: device,
                testResults: {},
                screenshots: {}
            };

            // Create browser instance with device configuration
            const browser = await remote({
                capabilities: {
                    browserName: 'chrome',
                    'goog:chromeOptions': {
                        mobileEmulation: {
                            deviceMetrics: {
                                width: device.width,
                                height: device.height,
                                pixelRatio: device.pixelRatio
                            },
                            userAgent: device.userAgent
                        }
                    }
                }
            });

            try {
                // Navigate to URL
                await browser.url(baseUrl);

                // Test portrait orientation
                await this.testDeviceOrientation(browser, device, 'portrait', results);

                // Test landscape orientation if applicable
                if (!device.isTablet && !device.isFoldable) {
                    await this.testDeviceOrientation(browser, device, 'landscape', results);
                }

                // Test responsive breakpoints
                await this.testResponsiveBreakpoints(browser, device, results);

                // Test touch interactions
                await this.testTouchInteractions(browser, device, results);

            } catch (error) {
                console.error(`Error testing ${device.name}:`, error);
                results[device.name].errors = error.message;
            } finally {
                await browser.deleteSession();
            }
        }

        return this.generateReport(results);
    }

    async testDeviceOrientation(browser, device, orientation, results) {
        const orientationKey = `${device.name}_${orientation}`;
        results[device.name].testResults[orientationKey] = [];

        // Set viewport size for orientation
        const [width, height] = orientation === 'portrait' 
            ? [device.width, device.height] 
            : [device.height, device.width];

        await browser.setWindowSize(width, height);

        // Take screenshot
        const screenshot = await browser.takeScreenshot();
        results[device.name].screenshots[orientation] = screenshot;

        // Run test cases for this orientation
        for (const testCase of this.testCases) {
            if (!testCase.orientations.includes(orientation)) {
                continue;
            }

            const testResult = await this.runTestCase(browser, testCase, device, orientation);
            results[device.name].testResults[orientationKey].push(testResult);
        }
    }

    async runTestCase(browser, testCase, device, orientation) {
        const result = {
            testName: testCase.name,
            orientation: orientation,
            passed: true,
            details: []
        };

        try {
            const elements = await browser.$$(testCase.selector);

            for (const element of elements) {
                for (const assertion of testCase.assertions) {
                    const assertionResult = await this.runAssertion(
                        element, assertion, device
                    );

                    if (!assertionResult.passed) {
                        result.passed = false;
                    }

                    result.details.push(assertionResult);
                }
            }
        } catch (error) {
            result.passed = false;
            result.details.push({
                error: error.message
            });
        }

        return result;
    }

    async runAssertion(element, assertionType, device) {
        const result = {
            assertion: assertionType,
            passed: true,
            message: ''
        };

        try {
            switch (assertionType) {
                case 'isDisplayed':
                    const isDisplayed = await element.isDisplayed();
                    result.passed = isDisplayed;
                    result.message = isDisplayed ? 'Element is visible' : 'Element not visible';
                    break;

                case 'hasMinimumSize':
                    const size = await element.getSize();
                    // Convert pixels to points (iOS) or dp (Android)
                    const minSize = 44; // 44 points/dp minimum
                    const widthPoints = device.platform === 'iOS' 
                        ? size.width / device.pixelRatio 
                        : size.width / (device.pixelRatio / 160);
                    const heightPoints = device.platform === 'iOS' 
                        ? size.height / device.pixelRatio 
                        : size.height / (device.pixelRatio / 160);

                    result.passed = widthPoints >= minSize && heightPoints >= minSize;
                    result.message = `Size: ${widthPoints.toFixed(1)}x${heightPoints.toFixed(1)} points`;
                    break;

                case 'isWithinViewport':
                    const location = await element.getLocation();
                    const viewportSize = await browser.getWindowSize();

                    const isInViewport = 
                        location.x >= 0 && 
                        location.y >= 0 &&
                        location.x < viewportSize.width &&
                        location.y < viewportSize.height;

                    result.passed = isInViewport;
                    result.message = isInViewport ? 'Element in viewport' : 'Element outside viewport';
                    break;

                default:
                    result.passed = true;
                    result.message = 'Assertion not implemented';
            }
        } catch (error) {
            result.passed = false;
            result.message = `Assertion error: ${error.message}`;
        }

        return result;
    }

    async testResponsiveBreakpoints(browser, device, results) {
        const breakpoints = [320, 375, 414, 768, 1024, 1280];
        results[device.name].breakpointTests = [];

        for (const width of breakpoints) {
            await browser.setWindowSize(width, device.height);

            // Check for layout shifts or overlaps
            const layoutTest = await this.checkLayoutIssues(browser);

            results[device.name].breakpointTests.push({
                width: width,
                layoutTest: layoutTest
            });
        }
    }

    async testTouchInteractions(browser, device, results) {
        results[device.name].touchTests = [];

        // Test tap accuracy
        const tapTest = await this.testTapAccuracy(browser, device);
        results[device.name].touchTests.push({
            type: 'tap_accuracy',
            result: tapTest
        });

        // Test scroll performance
        const scrollTest = await this.testScrollPerformance(browser, device);
        results[device.name].touchTests.push({
            type: 'scroll_performance',
            result: scrollTest
        });

        // Test multi-touch if applicable
        if (device.hasSPen || device.isTablet) {
            const multiTouchTest = await this.testMultiTouch(browser, device);
            results[device.name].touchTests.push({
                type: 'multi_touch',
                result: multiTouchTest
            });
        }
    }

    generateReport(results) {
        const report = {
            summary: {
                totalDevices: Object.keys(results).length,
                passedTests: 0,
                failedTests: 0,
                devicesWithIssues: []
            },
            detailedResults: results
        };

        // Calculate summary statistics
        for (const [deviceName, deviceResults] of Object.entries(results)) {
            let devicePassed = true;

            // Check orientation tests
            for (const [orientationKey, tests] of Object.entries(deviceResults.testResults)) {
                const failedTests = tests.filter(test => !test.passed);
                if (failedTests.length > 0) {
                    devicePassed = false;
                    report.summary.failedTests += failedTests.length;
                }
                report.summary.passedTests += tests.length - failedTests.length;
            }

            if (!devicePassed) {
                report.summary.devicesWithIssues.push(deviceName);
            }
        }

        return report;
    }
}

// Usage example
async function main() {
    const tester = new ResponsiveDesignTester();

    try {
        const report = await tester.runResponsiveTests('https://example.com/app');

        console.log('Responsive Design Test Report:');
        console.log(`Devices Tested: ${report.summary.totalDevices}`);
        console.log(`Tests Passed: ${report.summary.passedTests}`);
        console.log(`Tests Failed: ${report.summary.failedTests}`);

        if (report.summary.devicesWithIssues.length > 0) {
            console.log('\nDevices with issues:');
            report.summary.devicesWithIssues.forEach(device => {
                console.log(`- ${device}`);
            });
        }

        // Save detailed report
        const fs = require('fs');
        fs.writeFileSync('responsive-test-report.json', 
                        JSON.stringify(report, null, 2));

    } catch (error) {
        console.error('Test execution failed:', error);
    }
}

// Run if called directly
if (require.main === module) {
    main();
}

