// Android Hardware Capability Detection and Testing
package com.example.app.utils

import android.content.Context
import android.content.pm.PackageManager
import android.hardware.*
import android.os.Build
import android.os.Environment
import android.os.StatFs
import android.util.DisplayMetrics
import android.view.WindowManager
import java.io.File
import java.io.RandomAccessFile
import java.util.*

/**
 * Comprehensive hardware capability detection and testing utility
 * Detects device-specific hardware features and capabilities
 */
class HardwareCapabilityDetector(private val context: Context) {

    // Processor Information
    data class ProcessorInfo(
        val architecture: String,
        val cores: Int,
        val maxFrequency: Long, // in MHz
        val is64Bit: Boolean,
        val manufacturer: String,
        val model: String
    )

    // Memory Information
    data class MemoryInfo(
        val totalRAM: Long, // in bytes
        val availableRAM: Long,
        val thresholdRAM: Long,
        val isLowMemoryDevice: Boolean,
        val heapSize: Long
    )

    // Storage Information
    data class StorageInfo(
        val totalInternal: Long,
        val availableInternal: Long,
        val totalExternal: Long?,
        val availableExternal: Long?,
        val isExternalRemovable: Boolean,
        val storageType: String // eMMC, UFS, NVMe
    )

    // Sensor Information
    data class SensorInfo(
        val type: Int,
        val name: String,
        val vendor: String,
        val power: Float,
        val maxRange: Float,
        val resolution: Float,
        val isAvailable: Boolean
    )

    /**
     * Detect comprehensive processor information
     */
    fun detectProcessorInfo(): ProcessorInfo {
        return try {
            val arch = System.getProperty("os.arch") ?: "unknown"
            val cores = Runtime.getRuntime().availableProcessors()

            // Try to read CPU info from /proc/cpuinfo
            val cpuInfo = readCpuInfo()

            ProcessorInfo(
                architecture = arch,
                cores = cores,
                maxFrequency = detectMaxCpuFrequency(),
                is64Bit = Build.SUPPORTED_64_BIT_ABIS.isNotEmpty(),
                manufacturer = cpuInfo["manufacturer"] ?: "Unknown",
                model = cpuInfo["model"] ?: Build.HARDWARE
            )
        } catch (e: Exception) {
            ProcessorInfo(
                architecture = "unknown",
                cores = 1,
                maxFrequency = 0,
                is64Bit = false,
                manufacturer = "Unknown",
                model = "Unknown"
            )
        }
    }

    /**
     * Read CPU information from /proc/cpuinfo
     */
    private fun readCpuInfo(): Map<String, String> {
        val cpuInfo = mutableMapOf<String, String>()

        try {
            val file = File("/proc/cpuinfo")
            if (file.exists()) {
                file.readLines().forEach { line ->
                    val parts = line.split(":").map { it.trim() }
                    if (parts.size == 2) {
                        when (parts[0]) {
                            "Hardware" -> cpuInfo["model"] = parts[1]
                            "Processor" -> cpuInfo["model"] = parts[1]
                            "CPU implementer" -> {
                                val implementer = parts[1].toIntOrNull(16)
                                cpuInfo["manufacturer"] = when (implementer) {
                                    0x41 -> "ARM"
                                    0x51 -> "Qualcomm"
                                    0x53 -> "Samsung"
                                    0x56 -> "Marvell"
                                    0x69 -> "Intel"
                                    else -> "Unknown"
                                }
                            }
                        }
                    }
                }
            }
        } catch (e: Exception) {
            // Ignore, use defaults
        }

        return cpuInfo
    }

    /**
     * Detect maximum CPU frequency
     */
    private fun detectMaxCpuFrequency(): Long {
        return try {
            val maxFreqFile = File("/sys/devices/system/cpu/cpu0/cpufreq/cpuinfo_max_freq")
            if (maxFreqFile.exists()) {
                maxFreqFile.readText().trim().toLong() / 1000 // Convert to MHz
            } else {
                0L
            }
        } catch (e: Exception) {
            0L
        }
    }

    /**
     * Detect memory information
     */
    fun detectMemoryInfo(): MemoryInfo {
        val activityManager = context.getSystemService(Context.ACTIVITY_SERVICE) as android.app.ActivityManager
        val memoryInfo = android.app.ActivityManager.MemoryInfo()
        activityManager.getMemoryInfo(memoryInfo)

        val runtime = Runtime.getRuntime()

        return MemoryInfo(
            totalRAM = memoryInfo.totalMem,
            availableRAM = memoryInfo.availMem,
            thresholdRAM = memoryInfo.threshold,
            isLowMemoryDevice = memoryInfo.lowMemory,
            heapSize = runtime.maxMemory()
        )
    }

    /**
     * Detect storage information
     */
    fun detectStorageInfo(): StorageInfo {
        val internalStorage = Environment.getDataDirectory()
        val statFs = StatFs(internalStorage.path)

        val blockSize = statFs.blockSizeLong
        val totalBlocks = statFs.blockCountLong
        val availableBlocks = statFs.availableBlocksLong

        val totalInternal = totalBlocks * blockSize
        val availableInternal = availableBlocks * blockSize

        // Check external storage
        val externalStorage = Environment.getExternalStorageDirectory()
        var totalExternal: Long? = null
        var availableExternal: Long? = null
        var isExternalRemovable = false

        if (Environment.MEDIA_MOUNTED == Environment.getExternalStorageState()) {
            val externalStatFs = StatFs(externalStorage.path)
            val externalBlockSize = externalStatFs.blockSizeLong
            val externalTotalBlocks = externalStatFs.blockCountLong
            val externalAvailableBlocks = externalStatFs.availableBlocksLong

            totalExternal = externalTotalBlocks * externalBlockSize
            availableExternal = externalAvailableBlocks * externalBlockSize

            // Check if external storage is removable
            isExternalRemovable = Environment.isExternalStorageRemovable()
        }

        // Try to detect storage type
        val storageType = detectStorageType()

        return StorageInfo(
            totalInternal = totalInternal,
            availableInternal = availableInternal,
            totalExternal = totalExternal,
            availableExternal = availableExternal,
            isExternalRemovable = isExternalRemovable,
            storageType = storageType
        )
    }

    /**
     * Detect storage type (eMMC, UFS, NVMe)
     */
    private fun detectStorageType(): String {
        return try {
            // Check for UFS
            val ufsDir = File("/sys/class/ufs")
            if (ufsDir.exists() && ufsDir.list()?.isNotEmpty() == true) {
                return "UFS"
            }

            // Check for NVMe
            val nvmeDir = File("/sys/class/nvme")
            if (nvmeDir.exists()) {
                return "NVMe"
            }

            // Default to eMMC
            "eMMC"
        } catch (e: Exception) {
            "Unknown"
        }
    }

    /**
     * Detect available sensors
     */
    fun detectSensors(): List<SensorInfo> {
        val sensorManager = context.getSystemService(Context.SENSOR_SERVICE) as SensorManager
        val sensors = sensorManager.getSensorList(Sensor.TYPE_ALL)

        return sensors.map { sensor ->
            SensorInfo(
                type = sensor.type,
                name = sensor.name,
                vendor = sensor.vendor,
                power = sensor.power,
                maxRange = sensor.maximumRange,
                resolution = sensor.resolution,
                isAvailable = true
            )
        }
    }

    /**
     * Check for specific sensor availability
     */
    fun hasSensor(sensorType: Int): Boolean {
        val sensorManager = context.getSystemService(Context.SENSOR_SERVICE) as SensorManager
        return sensorManager.getDefaultSensor(sensorType) != null
    }

    /**
     * Detect display information
     */
    fun detectDisplayInfo(): DisplayMetrics {
        val windowManager = context.getSystemService(Context.WINDOW_SERVICE) as WindowManager
        val displayMetrics = DisplayMetrics()

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            val display = context.display
            display?.getRealMetrics(displayMetrics)
        } else {
            @Suppress("DEPRECATION")
            windowManager.defaultDisplay.getRealMetrics(displayMetrics)
        }

        return displayMetrics
    }

    /**
     * Check for specific hardware feature
     */
    fun hasHardwareFeature(feature: String): Boolean {
        return context.packageManager.hasSystemFeature(feature)
    }

    /**
     * Check for manufacturer-specific features
     */
    fun detectManufacturerFeatures(): Map<String, Boolean> {
        val manufacturer = Build.MANUFACTURER.lowercase(Locale.getDefault())
        val features = mutableMapOf<String, Boolean>()

        when (manufacturer) {
            "samsung" -> {
                // Samsung specific features
                features["has_spen"] = hasHardwareFeature("com.sec.feature.spen_usp")
                features["has_edge_screen"] = hasHardwareFeature("com.sec.feature.edge_screen")
                features["has_secure_folder"] = hasHardwareFeature("com.samsung.feature.samsung_experience_mobile")
            }
            "xiaomi" -> {
                // Xiaomi specific features
                features["has_infrared"] = hasHardwareFeature("xiaomi.hardware.ir")
            }
            "google" -> {
                // Google Pixel specific features
                features["has_titan_m"] = hasHardwareFeature("android.hardware.hardware_properties.titan_m")
            }
        }

        return features
    }

    /**
     * Run hardware compatibility tests
     */
    fun runHardwareCompatibilityTests(): Map<String, Any> {
        val results = mutableMapOf<String, Any>()

        // Processor tests
        val processorInfo = detectProcessorInfo()
        results["processor"] = processorInfo
        results["processor_compatibility"] = testProcessorCompatibility(processorInfo)

        // Memory tests
        val memoryInfo = detectMemoryInfo()
        results["memory"] = memoryInfo
        results["memory_compatibility"] = testMemoryCompatibility(memoryInfo)

        // Storage tests
        val storageInfo = detectStorageInfo()
        results["storage"] = storageInfo
        results["storage_compatibility"] = testStorageCompatibility(storageInfo)

        // Sensor tests
        val sensors = detectSensors()
        results["sensors"] = sensors
        results["sensor_compatibility"] = testSensorCompatibility(sensors)

        // Manufacturer features
        results["manufacturer_features"] = detectManufacturerFeatures()

        // Overall compatibility assessment
        results["compatibility_score"] = calculateCompatibilityScore(results)

        return results
    }

    private fun testProcessorCompatibility(processor: ProcessorInfo): Map<String, Any> {
        val tests = mutableMapOf<String, Any>()

        // Test 1: Check if processor meets minimum requirements
        tests["meets_minimum_cores"] = processor.cores >= 4
        tests["meets_minimum_frequency"] = processor.maxFrequency >= 1500 // 1.5 GHz
        tests["is_64_bit"] = processor.is64Bit

        // Test 2: Check for known problematic architectures
        val problematicArchs = listOf("armeabi-v7a", "x86")
        tests["has_problematic_architecture"] = problematicArchs.any { 
            processor.architecture.contains(it, ignoreCase = true) 
        }

        return tests
    }

    private fun testMemoryCompatibility(memory: MemoryInfo): Map<String, Any> {
        val tests = mutableMapOf<String, Any>()

        // Convert to MB for readability
        val totalMB = memory.totalRAM / (1024 * 1024)
        val availableMB = memory.availableRAM / (1024 * 1024)
        val heapMB = memory.heapSize / (1024 * 1024)

        tests["total_memory_mb"] = totalMB
        tests["available_memory_mb"] = availableMB
        tests["heap_size_mb"] = heapMB
        tests["is_low_memory"] = memory.isLowMemoryDevice

        // Test if memory meets requirements
        tests["meets_minimum_memory"] = totalMB >= 2000 // 2GB minimum
        tests["has_sufficient_available"] = availableMB >= 500 // 500MB available
        tests["heap_size_adequate"] = heapMB >= 256 // 256MB heap

        return tests
    }

    private fun testStorageCompatibility(storage: StorageInfo): Map<String, Any> {
        val tests = mutableMapOf<String, Any>()

        // Convert to GB for readability
        val totalInternalGB = storage.totalInternal / (1024 * 1024 * 1024)
        val availableInternalGB = storage.availableInternal / (1024 * 1024 * 1024)

        tests["total_internal_gb"] = totalInternalGB
        tests["available_internal_gb"] = availableInternalGB
        tests["has_external_storage"] = storage.totalExternal != null
        tests["storage_type"] = storage.storageType

        // Test storage requirements
        tests["meets_minimum_internal"] = totalInternalGB >= 16 // 16GB minimum
        tests["has_sufficient_space"] = availableInternalGB >= 2 // 2GB free space
        tests["is_fast_storage"] = storage.storageType == "UFS" || storage.storageType == "NVMe"

        return tests
    }

    private fun testSensorCompatibility(sensors: List<SensorInfo>): Map<String, Any> {
        val tests = mutableMapOf<String, Any>()

        // Check for essential sensors
        val essentialSensors = mapOf(
            Sensor.TYPE_ACCELEROMETER to "Accelerometer",
            Sensor.TYPE_GYROSCOPE to "Gyroscope",
            Sensor.TYPE_PROXIMITY to "Proximity",
            Sensor.TYPE_LIGHT to "Light Sensor"
        )

        essentialSensors.forEach { (type, name) ->
            tests[name] = sensors.any { it.type == type }
        }

        // Count total sensors
        tests["total_sensors"] = sensors.size

        // Check for advanced sensors
        val advancedSensors = mapOf(
            Sensor.TYPE_HEART_RATE to "Heart Rate Monitor",
            Sensor.TYPE_STEP_COUNTER to "Step Counter",
            Sensor.TYPE_FINGERPRINT to "Fingerprint Sensor"
        )

        advancedSensors.forEach { (type, name) ->
            tests[name] = sensors.any { it.type == type }
        }

        return tests
    }

    private fun calculateCompatibilityScore(results: Map<String, Any>): Int {
        var score = 100

        // Deduct points based on test results
        val processorTests = results["processor_compatibility"] as? Map<*, *>
        val memoryTests = results["memory_compatibility"] as? Map<*, *>
        val storageTests = results["storage_compatibility"] as? Map<*, *>

        // Processor deductions
        if (processorTests?.get("meets_minimum_cores") == false) score -= 20
        if (processorTests?.get("meets_minimum_frequency") == false) score -= 15
        if (processorTests?.get("is_64_bit") == false) score -= 10

        // Memory deductions
        if (memoryTests?.get("meets_minimum_memory") == false) score -= 25
        if (memoryTests?.get("is_low_memory") == true) score -= 15

        // Storage deductions
        if (storageTests?.get("meets_minimum_internal") == false) score -= 20
        if (storageTests?.get("has_sufficient_space") == false) score -= 10

        return maxOf(0, score) // Ensure score doesn't go below 0
    }

    /**
     * Generate hardware compatibility report
     */
    fun generateCompatibilityReport(): String {
        val testResults = runHardwareCompatibilityTests()
        val stringBuilder = StringBuilder()

        stringBuilder.append("Hardware Compatibility Report\n")
        stringBuilder.append("=".repeat(50)).append("\n\n")

        // Device Information
        stringBuilder.append("Device Information:\n")
        stringBuilder.append("- Manufacturer: ${Build.MANUFACTURER}\n")
        stringBuilder.append("- Model: ${Build.MODEL}\n")
        stringBuilder.append("- Android Version: ${Build.VERSION.RELEASE}\n\n")

        // Processor Information
        val processorInfo = testResults["processor"] as ProcessorInfo
        stringBuilder.append("Processor:\n")
        stringBuilder.append("- Architecture: ${processorInfo.architecture}\n")
        stringBuilder.append("- Cores: ${processorInfo.cores}\n")
        stringBuilder.append("- Max Frequency: ${processorInfo.maxFrequency} MHz\n")
        stringBuilder.append("- 64-bit: ${processorInfo.is64Bit}\n")
        stringBuilder.append("- Manufacturer: ${processorInfo.manufacturer}\n")
        stringBuilder.append("- Model: ${processorInfo.model}\n\n")

        // Memory Information
        val memoryInfo = testResults["memory"] as MemoryInfo
        val totalMB = memoryInfo.totalRAM / (1024 * 1024)
        val availableMB = memoryInfo.availableRAM / (1024 * 1024)
        stringBuilder.append("Memory:\n")
        stringBuilder.append("- Total RAM: ${totalMB} MB\n")
        stringBuilder.append("- Available RAM: ${availableMB} MB\n")
        stringBuilder.append("- Low Memory Device: ${memoryInfo.isLowMemoryDevice}\n\n")

        // Compatibility Score
        val score = testResults["compatibility_score"] as Int
        stringBuilder.append("Compatibility Score: $score/100\n")

        // Recommendations
        stringBuilder.append("\nRecommendations:\n")
        when {
            score >= 80 -> stringBuilder.append("- Device is highly compatible\n")
            score >= 60 -> stringBuilder.append("- Device is moderately compatible\n")
            else -> stringBuilder.append("- Device may have compatibility issues\n")
        }

        return stringBuilder.toString()
    }
}

