// iOS Hardware and Feature Detection
// Comprehensive hardware capability detection for iOS devices

import UIKit
import CoreMotion
import AVFoundation
import LocalAuthentication
import Network

/// Comprehensive hardware capability detector for iOS
class iOSHardwareDetector {

    // MARK: - Device Information

    struct DeviceInfo {
        let modelIdentifier: String
        let modelName: String
        let architecture: String
        let physicalMemory: UInt64 // in bytes
        let processorCount: Int
        let is64Bit: Bool
        let hasNeuralEngine: Bool
        let neuralEngineCores: Int?
    }

    struct ScreenInfo {
        let nativeBounds: CGRect
        let scale: CGFloat
        let maxBrightness: CGFloat
        let hasProMotion: Bool
        let refreshRate: CGFloat
        let isOLED: Bool
        let hasDynamicIsland: Bool
        let hasNotch: Bool
    }

    struct SensorInfo {
        let hasGyroscope: Bool
        let hasAccelerometer: Bool
        let hasMagnetometer: Bool
        let hasBarometer: Bool
        let hasFaceID: Bool
        let hasTouchID: Bool
        let hasLiDAR: Bool
        let hasProximitySensor: Bool
    }

    struct CameraInfo {
        let hasBackCamera: Bool
        let hasFrontCamera: Bool
        let backCameraCount: Int
        let maxBackCameraResolution: CGSize
        let maxFrontCameraResolution: CGSize
        let hasTelephoto: Bool
        let hasUltraWide: Bool
        let hasLiDAR: Bool
        let hasNightMode: Bool
    }

    // MARK: - Properties

    private let motionManager = CMMotionManager()
    private let device = UIDevice.current
    private let screen = UIScreen.main
    private let avSession = AVCaptureDevice.DiscoverySession(
        deviceTypes: [.builtInWideAngleCamera, .builtInTelephotoCamera, .builtInUltraWideCamera],
        mediaType: .video,
        position: .unspecified
    )

    // MARK: - Device Information Detection

    /// Get comprehensive device information
    func getDeviceInfo() -> DeviceInfo {
        let modelIdentifier = getModelIdentifier()

        return DeviceInfo(
            modelIdentifier: modelIdentifier,
            modelName: getModelName(from: modelIdentifier),
            architecture: getArchitecture(),
            physicalMemory: ProcessInfo.processInfo.physicalMemory,
            processorCount: ProcessInfo.processInfo.processorCount,
            is64Bit: MemoryLayout<Int>.size == 8,
            hasNeuralEngine: hasNeuralEngine(),
            neuralEngineCores: getNeuralEngineCoreCount()
        )
    }

    /// Get device model identifier (e.g., "iPhone15,2")
    private func getModelIdentifier() -> String {
        var systemInfo = utsname()
        uname(&systemInfo)

        let machineMirror = Mirror(reflecting: systemInfo.machine)
        let identifier = machineMirror.children.reduce("") { identifier, element in
            guard let value = element.value as? Int8, value != 0 else { return identifier }
            return identifier + String(UnicodeScalar(UInt8(value)))
        }

        return identifier
    }

    /// Get human-readable model name from identifier
    private func getModelName(from identifier: String) -> String {
        switch identifier {
            // iPhone Models
            case "iPhone15,2": return "iPhone 14 Pro"
            case "iPhone15,3": return "iPhone 14 Pro Max"
            case "iPhone15,4": return "iPhone 14"
            case "iPhone15,5": return "iPhone 14 Plus"
            case "iPhone16,1": return "iPhone 15 Pro"
            case "iPhone16,2": return "iPhone 15 Pro Max"
            case "iPhone16,3": return "iPhone 15"
            case "iPhone16,4": return "iPhone 15 Plus"

            // iPad Models
            case "iPad14,5", "iPad14,6": return "iPad Pro 11-inch (4th generation)"
            case "iPad14,3", "iPad14,4": return "iPad Pro 12.9-inch (6th generation)"

            // Simulator
            case "x86_64", "arm64": return "Simulator"

            default: return "Unknown Device"
        }
    }

    /// Get device architecture
    private func getArchitecture() -> String {
        #if arch(arm64)
            return "ARM64"
        #elseif arch(x86_64)
            return "x86_64"
        #else
            return "Unknown"
        #endif
    }

    /// Check if device has Neural Engine
    private func hasNeuralEngine() -> Bool {
        let modelIdentifier = getModelIdentifier()

        // Neural Engine was introduced with A11 Bionic (iPhone 8/X)
        // Check for devices with A11 or newer
        let devicesWithNeuralEngine = [
            "iPhone10,", // iPhone 8/8 Plus/X
            "iPhone11,", // iPhone XS/XS Max/XR
            "iPhone12,", // iPhone 11 series
            "iPhone13,", // iPhone 12 series
            "iPhone14,", // iPhone 13 series
            "iPhone15,", // iPhone 14 series
            "iPhone16,", // iPhone 15 series
            "iPad8,",   // iPad Pro 3rd gen
            "iPad11,",  // iPad Air 3rd gen
            "iPad12,",  // iPad 8th gen
            "iPad13,",  // iPad 9th gen
            "iPad14,"   // iPad 10th gen+
        ]

        return devicesWithNeuralEngine.contains { modelIdentifier.hasPrefix($0) }
    }

    /// Get Neural Engine core count
    private func getNeuralEngineCoreCount() -> Int? {
        let modelIdentifier = getModelIdentifier()

        switch modelIdentifier.prefix(7) {
            case "iPhone10": return 2  // A11 Bionic
            case "iPhone11": return 8  // A12 Bionic
            case "iPhone12": return 8  // A13 Bionic
            case "iPhone13": return 16 // A14 Bionic
            case "iPhone14": return 16 // A15 Bionic
            case "iPhone15": return 16 // A16 Bionic
            case "iPhone16": return 16 // A17 Pro
            default: return nil
        }
    }

    // MARK: - Screen Information Detection

    /// Get comprehensive screen information
    func getScreenInfo() -> ScreenInfo {
        let hasProMotion = screen.maximumFramesPerSecond >= 120

        return ScreenInfo(
            nativeBounds: screen.nativeBounds,
            scale: screen.scale,
            maxBrightness: screen.brightness,
            hasProMotion: hasProMotion,
            refreshRate: screen.maximumFramesPerSecond,
            isOLED: isOLEDDisplay(),
            hasDynamicIsland: hasDynamicIsland(),
            hasNotch: hasNotch()
        )
    }

    /// Check if device has OLED display
    private func isOLEDDisplay() -> Bool {
        let modelIdentifier = getModelIdentifier()

        // Devices with OLED displays
        let oledDevices = [
            "iPhone10,3", "iPhone10,6", // iPhone X
            "iPhone11,2", "iPhone11,4", "iPhone11,6", // iPhone XS/XS Max
            "iPhone12,1", "iPhone12,3", "iPhone12,5", // iPhone 11 Pro/Pro Max
            "iPhone13,1", "iPhone13,2", "iPhone13,3", "iPhone13,4", // iPhone 12 series
            "iPhone14,2", "iPhone14,3", "iPhone14,4", "iPhone14,5", // iPhone 13 series
            "iPhone15,2", "iPhone15,3", // iPhone 14 Pro/Pro Max
            "iPhone16,1", "iPhone16,2"  // iPhone 15 Pro/Pro Max
        ]

        return oledDevices.contains(modelIdentifier)
    }

    /// Check if device has Dynamic Island
    private func hasDynamicIsland() -> Bool {
        let modelIdentifier = getModelIdentifier()

        // Devices with Dynamic Island
        let dynamicIslandDevices = [
            "iPhone15,2", "iPhone15,3", // iPhone 14 Pro/Pro Max
            "iPhone16,1", "iPhone16,2", "iPhone16,3", "iPhone16,4" // iPhone 15 series
        ]

        return dynamicIslandDevices.contains(modelIdentifier)
    }

    /// Check if device has Notch
    private func hasNotch() -> Bool {
        let modelIdentifier = getModelIdentifier()

        // Devices with Notch (excluding Dynamic Island devices)
        let notchDevices = [
            "iPhone10,3", "iPhone10,6", // iPhone X
            "iPhone11,", // iPhone XS/XS Max/XR
            "iPhone12,", // iPhone 11 series
            "iPhone13,", // iPhone 12 series
            "iPhone14,", // iPhone 13 series
            "iPhone15,"  // iPhone 14 series
        ]

        return notchDevices.contains { modelIdentifier.hasPrefix($0) } && !hasDynamicIsland()
    }

    // MARK: - Sensor Detection

    /// Get comprehensive sensor information
    func getSensorInfo() -> SensorInfo {
        return SensorInfo(
            hasGyroscope: motionManager.isGyroAvailable,
            hasAccelerometer: motionManager.isAccelerometerAvailable,
            hasMagnetometer: motionManager.isMagnetometerAvailable,
            hasBarometer: CMAltimeter.isRelativeAltitudeAvailable(),
            hasFaceID: hasFaceID(),
            hasTouchID: hasTouchID(),
            hasLiDAR: hasLiDARScanner(),
            hasProximitySensor: device.isProximityMonitoringEnabled
        )
    }

    /// Check if device has Face ID
    private func hasFaceID() -> Bool {
        let context = LAContext()
        var error: NSError?

        // Check if device supports Face ID
        let canEvaluate = context.canEvaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, error: &error)

        if let laError = error as? LAError {
            return laError.code == .biometryNotAvailable ? false : true
        }

        // Check biometry type
        if #available(iOS 11.0, *) {
            return context.biometryType == .faceID
        }

        return false
    }

    /// Check if device has Touch ID
    private func hasTouchID() -> Bool {
        let context = LAContext()
        var error: NSError?

        let canEvaluate = context.canEvaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, error: &error)

        if #available(iOS 11.0, *) {
            return canEvaluate && context.biometryType == .touchID
        }

        return canEvaluate
    }

    /// Check if device has LiDAR scanner
    private func hasLiDARScanner() -> Bool {
        let modelIdentifier = getModelIdentifier()

        // Devices with LiDAR scanner
        let lidarDevices = [
            "iPad13,", // iPad Pro 4th gen (2020)
            "iPhone12,8", // iPhone 12 Pro
            "iPhone13,4", // iPhone 12 Pro Max
            "iPhone14,3", // iPhone 13 Pro
            "iPhone14,5", // iPhone 13 Pro Max
            "iPhone15,2", // iPhone 14 Pro
            "iPhone15,3", // iPhone 14 Pro Max
            "iPhone16,1", // iPhone 15 Pro
            "iPhone16,2"  // iPhone 15 Pro Max
        ]

        return lidarDevices.contains { modelIdentifier.hasPrefix($0) }
    }

    // MARK: - Camera Detection

    /// Get comprehensive camera information
    func getCameraInfo() -> CameraInfo {
        let backCameras = avSession.devices.filter { $0.position == .back }
        let frontCameras = avSession.devices.filter { $0.position == .front }

        var maxBackResolution = CGSize.zero
        var maxFrontResolution = CGSize.zero

        // Find maximum resolutions
        for format in backCameras.flatMap({ $0.formats }) {
            let dimensions = CMVideoFormatDescriptionGetDimensions(format.formatDescription)
            let resolution = CGSize(width: CGFloat(dimensions.width), height: CGFloat(dimensions.height))
            if resolution.width * resolution.height > maxBackResolution.width * maxBackResolution.height {
                maxBackResolution = resolution
            }
        }

        for format in frontCameras.flatMap({ $0.formats }) {
            let dimensions = CMVideoFormatDescriptionGetDimensions(format.formatDescription)
            let resolution = CGSize(width: CGFloat(dimensions.width), height: CGFloat(dimensions.height))
            if resolution.width * resolution.height > maxFrontResolution.width * maxFrontResolution.height {
                maxFrontResolution = resolution
            }
        }

        return CameraInfo(
            hasBackCamera: !backCameras.isEmpty,
            hasFrontCamera: !frontCameras.isEmpty,
            backCameraCount: backCameras.count,
            maxBackCameraResolution: maxBackResolution,
            maxFrontCameraResolution: maxFrontResolution,
            hasTelephoto: backCameras.contains { $0.deviceType == .builtInTelephotoCamera },
            hasUltraWide: backCameras.contains { $0.deviceType == .builtInUltraWideCamera },
            hasLiDAR: hasLiDARScanner(),
            hasNightMode: hasNightModeCapability()
        )
    }

    /// Check if device has night mode capability
    private func hasNightModeCapability() -> Bool {
        guard let backCamera = avSession.devices.first(where: { $0.position == .back }) else {
            return false
        }

        // Check for night mode capability (available on A12+ devices)
        if #available(iOS 13.0, *) {
            return backCamera.isLowLightBoostSupported
        }

        return false
    }

    // MARK: - Network Capabilities

    /// Check network capabilities
    func getNetworkCapabilities() -> [String: Bool] {
        var capabilities: [String: Bool] = [:]

        // Check for cellular capability
        #if !targetEnvironment(simulator)
        capabilities["hasCellular"] = CTTelephonyNetworkInfo().serviceSubscriberCellularProviders != nil
        #else
        capabilities["hasCellular"] = false
        #endif

        // Check for WiFi
        capabilities["hasWiFi"] = true // All iOS devices have WiFi

        // Check for 5G capability
        capabilities["has5G"] = has5GCapability()

        // Check for Bluetooth
        capabilities["hasBluetooth"] = true // All modern iOS devices have Bluetooth

        // Check for Ultra Wideband (U1 chip)
        capabilities["hasUltraWideband"] = hasUltraWideband()

        return capabilities
    }

    /// Check if device has 5G capability
    private func has5GCapability() -> Bool {
        let modelIdentifier = getModelIdentifier()

        // Devices with 5G capability
        let fiveGDevices = [
            "iPhone12,", // iPhone 12 series
            "iPhone13,", // iPhone 13 series
            "iPhone14,", // iPhone 14 series
            "iPhone15,", // iPhone 14 Pro series
            "iPhone16,", // iPhone 15 series
            "iPad13,",   // iPad Pro 5th gen+
            "iPad14,"    // iPad 10th gen+
        ]

        return fiveGDevices.contains { modelIdentifier.hasPrefix($0) }
    }

    /// Check if device has Ultra Wideband (U1 chip)
    private func hasUltraWideband() -> Bool {
        let modelIdentifier = getModelIdentifier()

        // Devices with U1 chip
        let uwbDevices = [
            "iPhone12,3", "iPhone12,5", // iPhone 11 Pro/Pro Max
            "iPhone13,", // iPhone 12 series
            "iPhone14,", // iPhone 13 series
            "iPhone15,", // iPhone 14 series
            "iPhone16,"  // iPhone 15 series
        ]

        return uwbDevices.contains { modelIdentifier.hasPrefix($0) }
    }

    // MARK: - Performance Testing

    /// Run basic performance tests
    func runPerformanceTests() -> [String: TimeInterval] {
        var results: [String: TimeInterval] = [:]

        // CPU performance test
        results["cpuTest"] = runCPUBenchmark()

        // Memory performance test
        results["memoryTest"] = runMemoryBenchmark()

        // Storage performance test
        results["storageTest"] = runStorageBenchmark()

        return results
    }

    private func runCPUBenchmark() -> TimeInterval {
        let startTime = CACurrentMediaTime()

        // Perform heavy computation
        var result: Double = 0
        for i in 0..<1_000_000 {
            result += sqrt(Double(i))
        }

        let endTime = CACurrentMediaTime()
        return endTime - startTime
    }

    private func runMemoryBenchmark() -> TimeInterval {
        let startTime = CACurrentMediaTime()

        // Allocate and deallocate large arrays
        for _ in 0..<100 {
            var largeArray = [Int](repeating: 0, count: 100_000)
            for i in 0..<largeArray.count {
                largeArray[i] = i * i
            }
        }

        let endTime = CACurrentMediaTime()
        return endTime - startTime
    }

    private func runStorageBenchmark() -> TimeInterval {
        let startTime = CACurrentMediaTime()

        // Write and read file test
        let tempFile = FileManager.default.temporaryDirectory.appendingPathComponent("benchmark.txt")
        let testData = Data(repeating: 65, count: 1_000_000) // 1MB of 'A's

        do {
            try testData.write(to: tempFile)
            let readData = try Data(contentsOf: tempFile)
            try FileManager.default.removeItem(at: tempFile)

            // Verify data integrity
            _ = readData.count
        } catch {
            return -1
        }

        let endTime = CACurrentMediaTime()
        return endTime - startTime
    }

    // MARK: - Compatibility Assessment

    /// Generate comprehensive compatibility report
    func generateCompatibilityReport() -> String {
        let deviceInfo = getDeviceInfo()
        let screenInfo = getScreenInfo()
        let sensorInfo = getSensorInfo()
        let cameraInfo = getCameraInfo()
        let networkCapabilities = getNetworkCapabilities()
        let performanceResults = runPerformanceTests()

        var report = """
        iOS Device Compatibility Report
        ===============================

        Device Information:
        - Model: \(deviceInfo.modelName)
        - Identifier: \(deviceInfo.modelIdentifier)
        - Architecture: \(deviceInfo.architecture)
        - Memory: \(deviceInfo.physicalMemory / 1_000_000_000) GB
        - Processor Cores: \(deviceInfo.processorCount)
        - Neural Engine: \(deviceInfo.hasNeuralEngine ? "Yes" : "No")

        Display Information:
        - Resolution: \(Int(screenInfo.nativeBounds.width))x\(Int(screenInfo.nativeBounds.height))
        - Scale: \(screenInfo.scale)
        - ProMotion: \(screenInfo.hasProMotion ? "Yes" : "No")
        - Refresh Rate: \(screenInfo.refreshRate) Hz
        - OLED: \(screenInfo.isOLED ? "Yes" : "No")
        - Dynamic Island: \(screenInfo.hasDynamicIsland ? "Yes" : "No")

        Sensor Information:
        - Accelerometer: \(sensorInfo.hasAccelerometer ? "Yes" : "No")
        - Gyroscope: \(sensorInfo.hasGyroscope ? "Yes" : "No")
        - Magnetometer: \(sensorInfo.hasMagnetometer ? "Yes" : "No")
        - Barometer: \(sensorInfo.hasBarometer ? "Yes" : "No")
        - Face ID: \(sensorInfo.hasFaceID ? "Yes" : "No")
        - Touch ID: \(sensorInfo.hasTouchID ? "Yes" : "No")
        - LiDAR: \(sensorInfo.hasLiDAR ? "Yes" : "No")

        Camera Information:
        - Back Cameras: \(cameraInfo.backCameraCount)
        - Max Back Resolution: \(Int(cameraInfo.maxBackCameraResolution.width))x\(Int(cameraInfo.maxBackCameraResolution.height))
        - Telephoto: \(cameraInfo.hasTelephoto ? "Yes" : "No")
        - Ultra Wide: \(cameraInfo.hasUltraWide ? "Yes" : "No")
        - Night Mode: \(cameraInfo.hasNightMode ? "Yes" : "No")

        Network Capabilities:
        - 5G: \(networkCapabilities["has5G"] ?? false ? "Yes" : "No")
        - Ultra Wideband: \(networkCapabilities["hasUltraWideband"] ?? false ? "Yes" : "No")

        Performance Results:
        - CPU Benchmark: \(String(format: "%.3f", performanceResults["cpuTest"] ?? 0)) seconds
        - Memory Benchmark: \(String(format: "%.3f", performanceResults["memoryTest"] ?? 0)) seconds
        - Storage Benchmark: \(String(format: "%.3f", performanceResults["storageTest"] ?? 0)) seconds

        """

        return report
    }
}

