// Android Touch Gesture Detector Implementation
package com.example.app.gestures

import android.content.Context
import android.view.GestureDetector
import android.view.MotionEvent
import android.view.ScaleGestureDetector
import android.view.View
import androidx.appcompat.app.AppCompatActivity
import android.os.Bundle
import android.widget.Toast
import kotlin.math.abs
import kotlin.math.atan2
import kotlin.math.pow

/**
 * Comprehensive touch gesture detector for Android
 * Handles single touch, multi-touch, and complex gestures
 */
class TouchGestureDetector(
    context: Context,
    private val gestureListener: TouchGestureListener
) {

    interface TouchGestureListener {
        fun onSingleTap(x: Float, y: Float): Boolean
        fun onDoubleTap(x: Float, y: Float): Boolean
        fun onLongPress(x: Float, y: Float): Boolean
        fun onSwipeLeft(): Boolean
        fun onSwipeRight(): Boolean
        fun onSwipeUp(): Boolean
        fun onSwipeDown(): Boolean
        fun onPinchStart(): Boolean
        fun onPinch(scaleFactor: Float, focusX: Float, focusY: Float): Boolean
        fun onPinchEnd(): Boolean
        fun onRotateStart(): Boolean
        fun onRotate(angleDelta: Float, focusX: Float, focusY: Float): Boolean
        fun onRotateEnd(): Boolean
        fun onDragStart(x: Float, y: Float): Boolean
        fun onDrag(x: Float, y: Float): Boolean
        fun onDragEnd(x: Float, y: Float): Boolean
        fun onMultiTouchStart(pointers: Int): Boolean
        fun onMultiTouchEnd(): Boolean
    }

    // Android's built-in gesture detectors
    private val gestureDetector: GestureDetector
    private val scaleGestureDetector: ScaleGestureDetector

    // Custom state tracking
    private var isDragging = false
    private var dragStartX = 0f
    private var dragStartY = 0f
    private var lastTouchTime = 0L
    private var touchSlop = 16f // Minimum distance for swipe
    private var isMultiTouchActive = false
    private var rotationAngle = 0f
    private var lastRotationAngle = 0f

    init {
        // Initialize Android's gesture detectors
        gestureDetector = GestureDetector(context, object : GestureDetector.SimpleOnGestureListener() {
            override fun onSingleTapConfirmed(e: MotionEvent): Boolean {
                return gestureListener.onSingleTap(e.x, e.y)
            }

            override fun onDoubleTap(e: MotionEvent): Boolean {
                return gestureListener.onDoubleTap(e.x, e.y)
            }

            override fun onLongPress(e: MotionEvent) {
                gestureListener.onLongPress(e.x, e.y)
            }

            override fun onFling(
                e1: MotionEvent?, 
                e2: MotionEvent, 
                velocityX: Float, 
                velocityY: Float
            ): Boolean {
                if (e1 == null) return false

                val deltaX = e2.x - e1.x
                val deltaY = e2.y - e1.y

                return if (abs(deltaX) > abs(deltaY)) {
                    // Horizontal swipe
                    if (deltaX > 0) gestureListener.onSwipeRight() 
                    else gestureListener.onSwipeLeft()
                } else {
                    // Vertical swipe
                    if (deltaY > 0) gestureListener.onSwipeDown() 
                    else gestureListener.onSwipeUp()
                }
            }

            override fun onScroll(
                e1: MotionEvent?, 
                e2: MotionEvent, 
                distanceX: Float, 
                distanceY: Float
            ): Boolean {
                // Handle basic scrolling if needed
                return false
            }
        })

        scaleGestureDetector = ScaleGestureDetector(context, object : ScaleGestureDetector.SimpleOnScaleGestureListener() {
            override fun onScaleBegin(detector: ScaleGestureDetector): Boolean {
                gestureListener.onPinchStart()
                return true
            }

            override fun onScale(detector: ScaleGestureDetector): Boolean {
                return gestureListener.onPinch(
                    detector.scaleFactor,
                    detector.focusX,
                    detector.focusY
                )
            }

            override fun onScaleEnd(detector: ScaleGestureDetector) {
                gestureListener.onPinchEnd()
            }
        })

        // Configure touch slop based on device density
        val density = context.resources.displayMetrics.density
        touchSlop = 16f * density
    }

    /**
     * Process touch events and detect gestures
     */
    fun onTouchEvent(event: MotionEvent): Boolean {
        val action = event.actionMasked
        val pointerCount = event.pointerCount

        // Track multi-touch state
        when (pointerCount) {
            1 -> {
                if (isMultiTouchActive) {
                    gestureListener.onMultiTouchEnd()
                    isMultiTouchActive = false
                }
            }
            else -> {
                if (!isMultiTouchActive) {
                    gestureListener.onMultiTouchStart(pointerCount)
                    isMultiTouchActive = true

                    // Initialize rotation tracking for multi-touch
                    if (pointerCount >= 2) {
                        rotationAngle = calculateRotationAngle(event)
                        lastRotationAngle = rotationAngle
                        gestureListener.onRotateStart()
                    }
                }
            }
        }

        // Handle multi-touch rotation
        if (pointerCount >= 2 && isMultiTouchActive) {
            val newRotationAngle = calculateRotationAngle(event)
            val angleDelta = newRotationAngle - lastRotationAngle

            if (abs(angleDelta) > 1) { // Minimum rotation threshold
                val focusX = (event.getX(0) + event.getX(1)) / 2
                val focusY = (event.getY(0) + event.getY(1)) / 2

                gestureListener.onRotate(angleDelta, focusX, focusY)
                lastRotationAngle = newRotationAngle
            }
        }

        // Process through Android's detectors
        scaleGestureDetector.onTouchEvent(event)
        gestureDetector.onTouchEvent(event)

        // Handle custom drag detection
        when (action) {
            MotionEvent.ACTION_DOWN -> {
                dragStartX = event.x
                dragStartY = event.y
                lastTouchTime = System.currentTimeMillis()

                // Start drag if not multi-touch
                if (pointerCount == 1) {
                    gestureListener.onDragStart(dragStartX, dragStartY)
                    isDragging = true
                }
            }

            MotionEvent.ACTION_MOVE -> {
                if (isDragging && pointerCount == 1) {
                    gestureListener.onDrag(event.x, event.y)
                }
            }

            MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                if (isDragging) {
                    gestureListener.onDragEnd(event.x, event.y)
                    isDragging = false
                }

                // End rotation if multi-touch was active
                if (isMultiTouchActive && pointerCount < 2) {
                    gestureListener.onRotateEnd()
                    gestureListener.onMultiTouchEnd()
                    isMultiTouchActive = false
                }
            }

            MotionEvent.ACTION_POINTER_UP -> {
                // Handle multi-touch pointer removal
                if (pointerCount - 1 < 2 && isMultiTouchActive) {
                    gestureListener.onRotateEnd()
                }
            }
        }

        return true
    }

    /**
     * Calculate rotation angle between two touch points
     */
    private fun calculateRotationAngle(event: MotionEvent): Float {
        if (event.pointerCount < 2) return 0f

        val deltaX = event.getX(1) - event.getX(0)
        val deltaY = event.getY(1) - event.getY(0)

        return Math.toDegrees(atan2(deltaY.toDouble(), deltaX.toDouble())).toFloat()
    }

    /**
     * Calculate distance between two touch points
     */
    private fun calculateDistance(event: MotionEvent): Float {
        if (event.pointerCount < 2) return 0f

        val deltaX = event.getX(1) - event.getX(0)
        val deltaY = event.getY(1) - event.getY(0)

        return kotlin.math.sqrt(deltaX.pow(2) + deltaY.pow(2))
    }

    /**
     * Configure gesture sensitivity
     */
    fun configureSensitivity(
        longPressTimeout: Int = 500, // milliseconds
        doubleTapTimeout: Int = 300,
        touchSlopPixels: Float = touchSlop
    ) {
        // These would configure the internal gesture detectors
        // Implementation depends on custom configuration needs
        // Note: Actual implementation would require modifying the gesture detectors
    }

    /**
     * Check if current touch movement exceeds touch slop threshold
     */
    private fun isTouchMovementSignificant(startX: Float, startY: Float, currentX: Float, currentY: Float): Boolean {
        val deltaX = abs(currentX - startX)
        val deltaY = abs(currentY - startY)
        val distance = kotlin.math.sqrt(deltaX.pow(2) + deltaY.pow(2))

        return distance > touchSlop
    }
}

