// Gesture Conflict Detection and Resolution Tool
// Identifies and helps resolve conflicting gesture handlers

class GestureConflictDetector {
    constructor() {
        this.registeredGestures = new Map();
        this.conflictLog = [];
        this.testResults = [];

        // Common gesture conflict patterns
        this.conflictPatterns = [
            {
                name: 'Swipe vs Scroll',
                description: 'Horizontal swipe conflicts with vertical scroll',
                detection: this.detectSwipeScrollConflict.bind(this),
                resolution: 'Implement directional locking or priority system'
            },
            {
                name: 'Tap vs Long Press',
                description: 'Tap gesture may be interpreted as failed long press',
                detection: this.detectTapLongPressConflict.bind(this),
                resolution: 'Adjust timing thresholds or implement tap cancellation'
            },
            {
                name: 'Pinch vs Two-Finger Scroll',
                description: 'Pinch gesture may interfere with two-finger scrolling',
                detection: this.detectPinchScrollConflict.bind(this),
                resolution: 'Differentiate based on initial finger movement pattern'
            },
            {
                name: 'Edge Swipe vs App Navigation',
                description: 'System edge gestures conflict with app navigation',
                detection: this.detectEdgeSwipeConflict.bind(this),
                resolution: 'Respect system gestures or provide user configuration'
            }
        ];
    }

    /**
     * Register a gesture handler for conflict detection
     */
    registerGesture(gestureConfig) {
        const gestureId = `${gestureConfig.type}_${Date.now()}_${Math.random()}`;

        this.registeredGestures.set(gestureId, {
            id: gestureId,
            ...gestureConfig,
            active: true,
            conflictCount: 0
        });

        this.detectConflicts();

        return gestureId;
    }

    /**
     * Unregister a gesture handler
     */
    unregisterGesture(gestureId) {
        this.registeredGestures.delete(gestureId);
    }

    /**
     * Detect conflicts between registered gestures
     */
    detectConflicts() {
        const gestures = Array.from(this.registeredGestures.values());
        const conflicts = [];

        // Check each pair of gestures for conflicts
        for (let i = 0; i < gestures.length; i++) {
            for (let j = i + 1; j < gestures.length; j++) {
                const conflict = this.checkGestureConflict(gestures[i], gestures[j]);
                if (conflict) {
                    conflicts.push(conflict);

                    // Update conflict counts
                    gestures[i].conflictCount++;
                    gestures[j].conflictCount++;
                }
            }
        }

        // Run pattern-based detection
        for (const pattern of this.conflictPatterns) {
            const patternConflicts = pattern.detection(gestures);
            if (patternConflicts.length > 0) {
                conflicts.push(...patternConflicts.map(c => ({
                    ...c,
                    pattern: pattern.name,
                    resolution: pattern.resolution
                })));
            }
        }

        // Log conflicts
        if (conflicts.length > 0) {
            this.logConflicts(conflicts);
        }

        return conflicts;
    }

    /**
     * Check for direct conflict between two gestures
     */
    checkGestureConflict(gesture1, gesture2) {
        // Check if gestures overlap in screen area
        const areaOverlap = this.checkAreaOverlap(gesture1, gesture2);

        // Check if gesture types could be confused
        const typeConflict = this.checkTypeConflict(gesture1.type, gesture2.type);

        // Check if timing could cause confusion
        const timingConflict = this.checkTimingConflict(gesture1, gesture2);

        if (areaOverlap && (typeConflict || timingConflict)) {
            return {
                gesture1: gesture1.id,
                gesture2: gesture2.id,
                type1: gesture1.type,
                type2: gesture2.type,
                area: gesture1.area || 'global',
                reason: typeConflict ? 'Gesture type confusion' : 'Timing conflict',
                severity: this.calculateConflictSeverity(gesture1, gesture2)
            };
        }

        return null;
    }

    /**
     * Check if gesture areas overlap
     */
    checkAreaOverlap(gesture1, gesture2) {
        // If either gesture is global, they overlap
        if (!gesture1.area || !gesture2.area) {
            return true;
        }

        // Simple rectangle overlap check
        const rect1 = gesture1.area;
        const rect2 = gesture2.area;

        return !(
            rect1.right < rect2.left ||
            rect1.left > rect2.right ||
            rect1.bottom < rect2.top ||
            rect1.top > rect2.bottom
        );
    }

    /**
     * Check if gesture types could conflict
     */
    checkTypeConflict(type1, type2) {
        const conflictPairs = [
            ['tap', 'doubleTap'],
            ['tap', 'longPress'],
            ['swipe', 'scroll'],
            ['pinch', 'twoFingerScroll'],
            ['swipe', 'drag'],
            ['horizontalSwipe', 'horizontalScroll']
        ];

        return conflictPairs.some(pair => 
            (pair[0] === type1 && pair[1] === type2) ||
            (pair[1] === type1 && pair[0] === type2)
        );
    }

    /**
     * Check timing conflicts
     */
    checkTimingConflict(gesture1, gesture2) {
        // If both gestures have similar timing requirements
        const similarTiming = 
            gesture1.minDuration && gesture2.minDuration &&
            Math.abs(gesture1.minDuration - gesture2.minDuration) < 200; // ms

        return similarTiming;
    }

    /**
     * Calculate conflict severity (1-5)
     */
    calculateConflictSeverity(gesture1, gesture2) {
        let severity = 1;

        // Increase severity for critical gestures
        if (gesture1.priority === 'high' || gesture2.priority === 'high') {
            severity += 1;
        }

        // Increase severity for overlapping areas
        if (gesture1.area && gesture2.area) {
            const overlapPercentage = this.calculateOverlapPercentage(gesture1.area, gesture2.area);
            if (overlapPercentage > 50) {
                severity += 1;
            }
            if (overlapPercentage > 80) {
                severity += 1;
            }
        }

        // Increase severity for similar gestures
        if (gesture1.type === gesture2.type) {
            severity += 1;
        }

        return Math.min(severity, 5);
    }

    /**
     * Calculate percentage overlap between two areas
     */
    calculateOverlapPercentage(rect1, rect2) {
        const xOverlap = Math.max(0, Math.min(rect1.right, rect2.right) - Math.max(rect1.left, rect2.left));
        const yOverlap = Math.max(0, Math.min(rect1.bottom, rect2.bottom) - Math.max(rect1.top, rect2.top));

        const overlapArea = xOverlap * yOverlap;
        const area1 = (rect1.right - rect1.left) * (rect1.bottom - rect1.top);

        return (overlapArea / area1) * 100;
    }

    /**
     * Pattern: Detect swipe vs scroll conflicts
     */
    detectSwipeScrollConflict(gestures) {
        const horizontalSwipes = gestures.filter(g => 
            g.type === 'swipe' && (g.direction === 'horizontal' || !g.direction)
        );

        const verticalScrolls = gestures.filter(g => 
            g.type === 'scroll' && (g.direction === 'vertical' || !g.direction)
        );

        const conflicts = [];

        for (const swipe of horizontalSwipes) {
            for (const scroll of verticalScrolls) {
                if (this.checkAreaOverlap(swipe, scroll)) {
                    conflicts.push({
                        gesture1: swipe.id,
                        gesture2: scroll.id,
                        type1: swipe.type,
                        type2: scroll.type,
                        reason: 'Horizontal swipe may interfere with vertical scroll',
                        severity: 3
                    });
                }
            }
        }

        return conflicts;
    }

    /**
     * Pattern: Detect tap vs long press conflicts
     */
    detectTapLongPressConflict(gestures) {
        const taps = gestures.filter(g => g.type === 'tap');
        const longPresses = gestures.filter(g => g.type === 'longPress');

        const conflicts = [];

        for (const tap of taps) {
            for (const longPress of longPresses) {
                if (this.checkAreaOverlap(tap, longPress)) {
                    conflicts.push({
                        gesture1: tap.id,
                        gesture2: longPress.id,
                        type1: tap.type,
                        type2: longPress.type,
                        reason: 'Tap may be interpreted as failed long press',
                        severity: 2
                    });
                }
            }
        }

        return conflicts;
    }

    /**
     * Pattern: Detect pinch vs two-finger scroll conflicts
     */
    detectPinchScrollConflict(gestures) {
        const pinches = gestures.filter(g => g.type === 'pinch' || g.type === 'zoom');
        const twoFingerScrolls = gestures.filter(g => 
            g.type === 'scroll' && g.fingers === 2
        );

        const conflicts = [];

        for (const pinch of pinches) {
            for (const scroll of twoFingerScrolls) {
                if (this.checkAreaOverlap(pinch, scroll)) {
                    conflicts.push({
                        gesture1: pinch.id,
                        gesture2: scroll.id,
                        type1: pinch.type,
                        type2: scroll.type,
                        reason: 'Pinch/zoom may interfere with two-finger scroll',
                        severity: 3
                    });
                }
            }
        }

        return conflicts;
    }

    /**
     * Pattern: Detect edge swipe conflicts
     */
    detectEdgeSwipeConflict(gestures) {
        const edgeSwipes = gestures.filter(g => 
            g.type === 'swipe' && g.area && this.isEdgeArea(g.area)
        );

        const conflicts = [];

        for (const edgeSwipe of edgeSwipes) {
            // Check for other gestures in the same edge area
            for (const gesture of gestures) {
                if (gesture.id !== edgeSwipe.id && this.checkAreaOverlap(edgeSwipe, gesture)) {
                    conflicts.push({
                        gesture1: edgeSwipe.id,
                        gesture2: gesture.id,
                        type1: edgeSwipe.type,
                        type2: gesture.type,
                        reason: 'Edge swipe may conflict with system gestures or other app gestures',
                        severity: 4
                    });
                }
            }
        }

        return conflicts;
    }

    /**
     * Check if area is at screen edge
     */
    isEdgeArea(area) {
        const edgeThreshold = 50; // pixels

        return (
            area.left < edgeThreshold ||          // Left edge
            area.top < edgeThreshold ||           // Top edge
            area.right > (screen.width - edgeThreshold) ||  // Right edge
            area.bottom > (screen.height - edgeThreshold)   // Bottom edge
        );
    }

    /**
     * Log conflicts for analysis
     */
    logConflicts(conflicts) {
        const timestamp = new Date().toISOString();

        for (const conflict of conflicts) {
            this.conflictLog.push({
                timestamp,
                ...conflict
            });

            console.warn(`Gesture Conflict Detected:`);
            console.warn(`  Gestures: ${conflict.gesture1} (${conflict.type1}) vs ${conflict.gesture2} (${conflict.type2})`);
            console.warn(`  Reason: ${conflict.reason}`);
            console.warn(`  Severity: ${conflict.severity}/5`);
            if (conflict.pattern) {
                console.warn(`  Pattern: ${conflict.pattern}`);
                console.warn(`  Resolution: ${conflict.resolution}`);
            }
            console.warn('');
        }
    }

    /**
     * Run comprehensive gesture conflict tests
     */
    runConflictTests() {
        console.log('Running gesture conflict tests...');

        // Test 1: Basic conflict detection
        this.testBasicConflicts();

        // Test 2: Pattern-based detection
        this.testPatternConflicts();

        // Test 3: Performance under multiple gestures
        this.testPerformanceConflicts();

        // Generate report
        const report = this.generateTestReport();

        console.log(`Conflict tests completed. Found ${report.totalConflicts} conflicts.`);

        return report;
    }

    testBasicConflicts() {
        // Register test gestures
        const tapId = this.registerGesture({
            type: 'tap',
            area: { left: 100, top: 100, right: 200, bottom: 200 },
            priority: 'medium'
        });

        const longPressId = this.registerGesture({
            type: 'longPress',
            area: { left: 150, top: 150, right: 250, bottom: 250 },
            minDuration: 500,
            priority: 'medium'
        });

        // This should detect a conflict
        const conflicts = this.detectConflicts();

        this.testResults.push({
            test: 'Basic Conflict Detection',
            passed: conflicts.length > 0,
            conflicts: conflicts
        });

        // Clean up
        this.unregisterGesture(tapId);
        this.unregisterGesture(longPressId);
    }

    testPatternConflicts() {
        // Register gestures that create pattern conflicts
        const swipeId = this.registerGesture({
            type: 'swipe',
            direction: 'horizontal',
            area: { left: 0, top: 300, right: 400, bottom: 500 },
            priority: 'high'
        });

        const scrollId = this.registerGesture({
            type: 'scroll',
            direction: 'vertical',
            area: { left: 0, top: 300, right: 400, bottom: 500 },
            priority: 'high'
        });

        const conflicts = this.detectConflicts();

        this.testResults.push({
            test: 'Pattern Conflict Detection',
            passed: conflicts.length > 0,
            conflicts: conflicts,
            patterns: conflicts.filter(c => c.pattern).map(c => c.pattern)
        });

        // Clean up
        this.unregisterGesture(swipeId);
        this.unregisterGesture(scrollId);
    }

    testPerformanceConflicts() {
        // Register many gestures to test performance
        const gestureIds = [];

        for (let i = 0; i < 20; i++) {
            const id = this.registerGesture({
                type: ['tap', 'swipe', 'scroll'][i % 3],
                area: {
                    left: (i % 5) * 80,
                    top: Math.floor(i / 5) * 80,
                    right: (i % 5) * 80 + 70,
                    bottom: Math.floor(i / 5) * 80 + 70
                },
                priority: i % 3 === 0 ? 'high' : 'medium'
            });
            gestureIds.push(id);
        }

        const startTime = performance.now();
        const conflicts = this.detectConflicts();
        const detectionTime = performance.now() - startTime;

        this.testResults.push({
            test: 'Performance Under Load',
            passed: detectionTime < 100, // Should complete in under 100ms
            conflicts: conflicts.length,
            detectionTime: detectionTime,
            gestureCount: gestureIds.length
        });

        // Clean up
        gestureIds.forEach(id => this.unregisterGesture(id));
    }

    /**
     * Generate comprehensive test report
     */
    generateTestReport() {
        const totalConflicts = this.conflictLog.length;
        const highSeverityConflicts = this.conflictLog.filter(c => c.severity >= 4).length;

        const testPassed = this.testResults.every(r => r.passed);
        const testFailures = this.testResults.filter(r => !r.passed);

        const report = {
            timestamp: new Date().toISOString(),
            summary: {
                totalConflicts,
                highSeverityConflicts,
                testPassed,
                testFailureCount: testFailures.length
            },
            testResults: this.testResults,
            conflicts: this.conflictLog,
            recommendations: this.generateRecommendations()
        };

        return report;
    }

    /**
     * Generate recommendations based on detected conflicts
     */
    generateRecommendations() {
        const recommendations = [];

        // Group conflicts by pattern
        const patternGroups = {};
        this.conflictLog.forEach(conflict => {
            const pattern = conflict.pattern || 'general';
            if (!patternGroups[pattern]) {
                patternGroups[pattern] = [];
            }
            patternGroups[pattern].push(conflict);
        });

        // Generate pattern-specific recommendations
        for (const [pattern, conflicts] of Object.entries(patternGroups)) {
            if (pattern === 'Swipe vs Scroll') {
                recommendations.push({
                    pattern,
                    suggestion: 'Implement directional locking or gesture priority system',
                    severity: 'High',
                    affectedGestures: conflicts.map(c => `${c.type1}/${c.type2}`).join(', ')
                });
            } else if (pattern === 'Tap vs Long Press') {
                recommendations.push({
                    pattern,
                    suggestion: 'Adjust timing thresholds or implement tap cancellation on move',
                    severity: 'Medium',
                    affectedGestures: conflicts.map(c => `${c.type1}/${c.type2}`).join(', ')
                });
            } else if (pattern === 'Edge Swipe vs App Navigation') {
                recommendations.push({
                    pattern,
                    suggestion: 'Respect system gesture areas or provide user configuration',
                    severity: 'High',
                    affectedGestures: conflicts.map(c => `${c.type1}/${c.type2}`).join(', ')
                });
            }
        }

        // General recommendations
        if (this.conflictLog.length > 10) {
            recommendations.push({
                pattern: 'General',
                suggestion: 'Consider reducing gesture density in overlapping areas',
                severity: 'Medium',
                affectedGestures: 'Multiple'
            });
        }

        const highSeverityCount = this.conflictLog.filter(c => c.severity >= 4).length;
        if (highSeverityCount > 0) {
            recommendations.push({
                pattern: 'General',
                suggestion: 'Address high severity conflicts first as they impact user experience most',
                severity: 'High',
                affectedGestures: `${highSeverityCount} high severity conflicts`
            });
        }

        return recommendations;
    }
}

