// Network Monitoring Service Worker for Mobile Web Applications
// Provides real-time network monitoring and adaptive behavior

class NetworkMonitor {
    constructor() {
        this.connection = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
        this.networkInfo = {
            effectiveType: 'unknown',
            downlink: 0,
            rtt: 0,
            saveData: false,
            type: 'unknown',
            lastUpdate: null
        };

        this.listeners = {
            change: [],
            offline: [],
            online: []
        };

        this.metricsHistory = [];
        this.maxHistorySize = 100;
        this.initialized = false;
    }

    initialize() {
        if (this.initialized) return;

        // Check if Network Information API is available
        if (this.connection) {
            this._updateNetworkInfo();

            // Listen for network changes
            this.connection.addEventListener('change', () => {
                this._handleNetworkChange();
            });

            console.log('Network Information API available');
        } else {
            console.warn('Network Information API not available, using fallback');
            this._setupFallbackMonitoring();
        }

        // Listen for online/offline events
        window.addEventListener('offline', () => {
            this._handleOffline();
        });

        window.addEventListener('online', () => {
            this._handleOnline();
        });

        this.initialized = true;
        console.log('Network Monitor initialized');
    }

    _updateNetworkInfo() {
        if (!this.connection) return;

        const oldInfo = {...this.networkInfo};

        this.networkInfo = {
            effectiveType: this.connection.effectiveType || 'unknown',
            downlink: this.connection.downlink || 0,
            rtt: this.connection.rtt || 0,
            saveData: this.connection.saveData || false,
            type: this.connection.type || 'unknown',
            lastUpdate: new Date().toISOString()
        };

        // Store in history
        this.metricsHistory.push({
            timestamp: this.networkInfo.lastUpdate,
            ...this.networkInfo
        });

        // Trim history if needed
        if (this.metricsHistory.length > this.maxHistorySize) {
            this.metricsHistory = this.metricsHistory.slice(-this.maxHistorySize);
        }

        // Check if network actually changed
        if (this._hasNetworkChanged(oldInfo, this.networkInfo)) {
            this._notifyListeners('change', this.networkInfo);
        }
    }

    _hasNetworkChanged(oldInfo, newInfo) {
        return (
            oldInfo.effectiveType !== newInfo.effectiveType ||
            oldInfo.type !== newInfo.type ||
            Math.abs(oldInfo.downlink - newInfo.downlink) > 0.1 ||
            Math.abs(oldInfo.rtt - newInfo.rtt) > 10
        );
    }

    _handleNetworkChange() {
        console.log('Network connection changed');
        this._updateNetworkInfo();

        // Log the change
        console.log(`Network changed to: ${this.networkInfo.effectiveType}, ` +
                   `Downlink: ${this.networkInfo.downlink} Mbps, ` +
                   `RTT: ${this.networkInfo.rtt} ms`);
    }

    _handleOffline() {
        console.log('Device went offline');
        this.networkInfo.effectiveType = 'offline';
        this.networkInfo.type = 'none';
        this.networkInfo.lastUpdate = new Date().toISOString();

        this._notifyListeners('offline', this.networkInfo);
    }

    _handleOnline() {
        console.log('Device came online');
        this._updateNetworkInfo();
        this._notifyListeners('online', this.networkInfo);
    }

    _setupFallbackMonitoring() {
        // Fallback: Use periodic fetch requests to detect network quality
        setInterval(() => {
            this._measureNetworkQuality();
        }, 30000); // Check every 30 seconds
    }

    async _measureNetworkQuality() {
        try {
            const testUrl = 'https://httpbin.org/get?cache=' + Date.now();
            const startTime = performance.now();

            const response = await fetch(testUrl, {
                method: 'GET',
                cache: 'no-store',
                mode: 'no-cors'
            });

            const endTime = performance.now();
            const latency = endTime - startTime;

            // Estimate network type based on latency
            let estimatedType = 'unknown';
            if (latency < 50) estimatedType = '4g';
            else if (latency < 200) estimatedType = '3g';
            else if (latency < 1000) estimatedType = '2g';
            else estimatedType = 'slow-2g';

            this.networkInfo = {
                effectiveType: estimatedType,
                downlink: this._estimateDownlink(latency),
                rtt: Math.round(latency),
                saveData: false,
                type: 'estimated',
                lastUpdate: new Date().toISOString()
            };

            this._notifyListeners('change', this.networkInfo);

        } catch (error) {
            // Assume offline if fetch fails
            this._handleOffline();
        }
    }

    _estimateDownlink(latency) {
        // Very rough estimation based on latency
        if (latency < 50) return 10; // ~10 Mbps for good 4G
        if (latency < 100) return 5;  // ~5 Mbps for average 4G
        if (latency < 200) return 2;  // ~2 Mbps for 3G
        if (latency < 500) return 0.5; // ~500 Kbps for slow 3G
        return 0.1; // ~100 Kbps for 2G
    }

    // Public API
    getCurrentNetworkInfo() {
        return {...this.networkInfo};
    }

    getNetworkHistory() {
        return [...this.metricsHistory];
    }

    isConnectionSlow() {
        const slowTypes = ['slow-2g', '2g', '3g'];
        return slowTypes.includes(this.networkInfo.effectiveType) || 
               this.networkInfo.rtt > 300 || 
               this.networkInfo.downlink < 1;
    }

    isConnectionFast() {
        return this.networkInfo.effectiveType === '4g' && 
               this.networkInfo.rtt < 100 && 
               this.networkInfo.downlink > 5;
    }

    isSaveDataEnabled() {
        return this.networkInfo.saveData;
    }

    isOffline() {
        return this.networkInfo.effectiveType === 'offline' || 
               this.networkInfo.type === 'none';
    }

    addEventListener(event, callback) {
        if (this.listeners[event]) {
            this.listeners[event].push(callback);
        }
    }

    removeEventListener(event, callback) {
        if (this.listeners[event]) {
            this.listeners[event] = this.listeners[event].filter(cb => cb !== callback);
        }
    }

    _notifyListeners(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(callback => {
                try {
                    callback(data);
                } catch (error) {
                    console.error(`Error in ${event} listener:`, error);
                }
            });
        }
    }

    // Adaptive loading based on network conditions
    async adaptiveFetch(url, options = {}) {
        const networkAwareOptions = {
            ...options,
            signal: AbortSignal.timeout(this._getTimeoutBasedOnNetwork())
        };

        if (this.isConnectionSlow() || this.isSaveDataEnabled()) {
            // Add headers for data saving
            networkAwareOptions.headers = {
                ...networkAwareOptions.headers,
                'Save-Data': 'on'
            };
        }

        try {
            const response = await fetch(url, networkAwareOptions);
            return response;
        } catch (error) {
            if (error.name === 'TimeoutError') {
                console.warn(`Request to ${url} timed out due to slow network`);
                throw new Error(`Request timeout (network: ${this.networkInfo.effectiveType})`);
            }
            throw error;
        }
    }

    _getTimeoutBasedOnNetwork() {
        switch (this.networkInfo.effectiveType) {
            case 'slow-2g': return 30000; // 30 seconds
            case '2g': return 20000;      // 20 seconds
            case '3g': return 10000;      // 10 seconds
            case '4g': return 5000;       // 5 seconds
            default: return 10000;        // 10 seconds default
        }
    }

    // Generate network report
    generateNetworkReport() {
        return {
            timestamp: new Date().toISOString(),
            currentNetwork: this.getCurrentNetworkInfo(),
            history: this.getNetworkHistory(),
            summary: {
                isOffline: this.isOffline(),
                isSlow: this.isConnectionSlow(),
                isFast: this.isConnectionFast(),
                saveData: this.isSaveDataEnabled(),
                timeSpentOffline: this._calculateTimeOffline(),
                networkStability: this._calculateNetworkStability()
            }
        };
    }

    _calculateTimeOffline() {
        const offlineEvents = this.metricsHistory.filter(m => m.effectiveType === 'offline');
        return offlineEvents.length; // Could be enhanced to calculate actual duration
    }

    _calculateNetworkStability() {
        if (this.metricsHistory.length < 2) return 'unknown';

        const changes = [];
        for (let i = 1; i < this.metricsHistory.length; i++) {
            if (this._hasNetworkChanged(this.metricsHistory[i-1], this.metricsHistory[i])) {
                changes.push(this.metricsHistory[i]);
            }
        }

        const changeRate = changes.length / this.metricsHistory.length;

        if (changeRate < 0.1) return 'very-stable';
        if (changeRate < 0.3) return 'stable';
        if (changeRate < 0.6) return 'unstable';
        return 'very-unstable';
    }
}

// Service Worker Integration
if (typeof self !== 'undefined' && self.registration) {
    // Running in Service Worker context
    const networkMonitor = new NetworkMonitor();
    networkMonitor.initialize();

    // Store network monitor in global scope for access from pages
    self.networkMonitor = networkMonitor;

    // Listen for messages from clients
    self.addEventListener('message', (event) => {
        if (event.data && event.data.type === 'GET_NETWORK_INFO') {
            event.ports[0].postMessage({
                type: 'NETWORK_INFO',
                data: networkMonitor.getCurrentNetworkInfo()
            });
        }
    });

    // Intercept fetch requests for adaptive behavior
    self.addEventListener('fetch', (event) => {
        if (networkMonitor.isConnectionSlow()) {
            // For slow connections, consider serving cached versions
            const url = new URL(event.request.url);

            // Don't intercept API calls or non-GET requests
            if (event.request.method !== 'GET' || 
                url.pathname.includes('/api/') ||
                url.pathname.includes('/auth/')) {
                return;
            }

            event.respondWith(
                networkMonitor.adaptiveFetch(event.request.url)
                    .catch(() => {
                        // Fallback to cache on network failure
                        return caches.match(event.request);
                    })
            );
        }
    });
}

