            // Update UI based on network
            updateUIForNetwork(networkInfo);

            // Adjust application behavior
            adjustAppBehaviorForNetwork(networkInfo);
        });

        networkMonitor.addEventListener('offline', () => {
            showOfflineNotification();
            enableOfflineMode();
        });

        networkMonitor.addEventListener('online', () => {
            showOnlineNotification();
            disableOfflineMode();
            syncOfflineData();
        });

        // Initial UI update
        updateUIForNetwork(networkMonitor.getCurrentNetworkInfo());

        function updateUIForNetwork(networkInfo) {
            const networkIndicator = document.getElementById('network-indicator');
            if (networkIndicator) {
                networkIndicator.className = `network-${networkInfo.effectiveType}`;
                networkIndicator.title = `Network: ${networkInfo.effectiveType}\n` +
                                       `Speed: ${networkInfo.downlink} Mbps\n` +
                                       `Latency: ${networkInfo.rtt} ms`;

                // Update text
                const textElement = networkIndicator.querySelector('.network-text');
                if (textElement) {
                    textElement.textContent = networkInfo.effectiveType.toUpperCase();
                }
            }
        }

        function adjustAppBehaviorForNetwork(networkInfo) {
            // Adjust image quality
            const images = document.querySelectorAll('img[data-src], img[data-src-low]');
            images.forEach(img => {
                if (networkMonitor.isConnectionSlow()) {
                    // Load low quality images on slow networks
                    const lowSrc = img.getAttribute('data-src-low');
                    if (lowSrc && img.src !== lowSrc) {
                        img.src = lowSrc;
                    }
                } else {
                    // Load high quality images on fast networks
                    const highSrc = img.getAttribute('data-src');
                    if (highSrc && img.src !== highSrc) {
                        img.src = highSrc;
                    }
                }
            });

            // Adjust video quality
            const videos = document.querySelectorAll('video');
            videos.forEach(video => {
                if (networkMonitor.isConnectionSlow()) {
                    video.preload = 'metadata';
                } else {
                    video.preload = 'auto';
                }
            });

            // Adjust polling intervals
            if (window.appPoller) {
                if (networkMonitor.isConnectionSlow()) {
                    window.appPoller.setInterval(60000); // 1 minute on slow networks
                } else {
                    window.appPoller.setInterval(10000); // 10 seconds on fast networks
                }
            }
        }

        function showOfflineNotification() {
            // Show offline notification
            const notification = document.createElement('div');
            notification.className = 'offline-notification';
            notification.textContent = 'You are currently offline. Some features may be limited.';
            document.body.appendChild(notification);

            setTimeout(() => {
                notification.remove();
            }, 5000);
        }

        function showOnlineNotification() {
            // Show online notification
            const notification = document.createElement('div');
            notification.className = 'online-notification';
            notification.textContent = 'You are back online!';
            document.body.appendChild(notification);

            setTimeout(() => {
                notification.remove();
            }, 3000);
        }

        function enableOfflineMode() {
            // Enable offline features
            document.body.classList.add('offline-mode');

            // Disable non-essential features
            const nonEssentialButtons = document.querySelectorAll('[data-non-essential]');
            nonEssentialButtons.forEach(btn => {
                btn.disabled = true;
            });
        }

        function disableOfflineMode() {
            // Disable offline mode
            document.body.classList.remove('offline-mode');

            // Re-enable features
            const nonEssentialButtons = document.querySelectorAll('[data-non-essential]');
            nonEssentialButtons.forEach(btn => {
                btn.disabled = false;
            });
        }

        function syncOfflineData() {
            // Sync any data collected while offline
            console.log('Syncing offline data...');
            // Implementation depends on your app's offline storage
        }

        // Export for use in other modules
        window.NetworkMonitor = NetworkMonitor;
    }
});

