    /**
     * Custom IdlingResource for network operations
     */
    class NetworkIdlingResource implements IdlingResource {
        private ResourceCallback resourceCallback;
        private boolean isIdle = true;

        @Override
        public String getName() {
            return NetworkIdlingResource.class.getName();
        }

        @Override
        public boolean isIdleNow() {
            return isIdle;
        }

        @Override
        public void registerIdleTransitionCallback(ResourceCallback callback) {
            this.resourceCallback = callback;
        }

        public void waitForIdle() {
            isIdle = false;
            // In real implementation, you would track ongoing network requests
            // This is a simplified version
            new Thread(() -> {
                try {
                    Thread.sleep(5000);  // Wait for network operations
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                isIdle = true;
                if (resourceCallback != null) {
                    resourceCallback.onTransitionToIdle();
                }
            }).start();
        }
    }
