class NetworkTestMatchers {

    public static Matcher<View> hasLowResImages() {
        return new TypeSafeMatcher<View>() {
            @Override
            public void describeTo(Description description) {
                description.appendText("has low resolution images");
            }

            @Override
            protected boolean matchesSafely(View view) {
                // Check if images in the view are low resolution
                // Implementation depends on your app structure
                return true;
            }
        };
    }

    public static Matcher<View> not(final Matcher<View> matcher) {
        return new BaseMatcher<View>() {
            @Override
            public boolean matches(Object item) {
                return !matcher.matches(item);
            }

            @Override
            public void describeTo(Description description) {
                description.appendText("not ").appendDescriptionOf(matcher);
            }
        };
    }
}

