            userInput = it.getString(KEY_USER_INPUT, "")
            operationProgress = it.getInt(KEY_PROGRESS, 0)
            isCriticalOperationRunning = it.getBoolean(KEY_CRITICAL_OP, false)

            // Restore UI state
            restoreUIState()
        }
    }

    override fun onSaveInstanceState(outState: Bundle) {
        super.onSaveInstanceState(outState)

        // Save all critical state
        outState.putString(KEY_USER_INPUT, userInput)
        outState.putInt(KEY_PROGRESS, operationProgress)
        outState.putBoolean(KEY_CRITICAL_OP, isCriticalOperationRunning)

        // Save form data
        saveFormState(outState)

        // Save scroll position
        outState.putInt(KEY_SCROLL_POSITION, recyclerView.computeVerticalScrollOffset())
    }

    override fun onPause() {
        super.onPause()

        // Save to persistent storage for longer interruptions
        if (isFinishing || isChangingConfigurations) {
            saveToDatabase()
        }

        // Pause ongoing operations
        pauseMediaPlayback()
        pauseNetworkOperations()

        // Release resources
        camera?.release()
    }

    override fun onResume() {
        super.onResume()

        // Restore operations
        resumeMediaPlayback()
        resumeNetworkOperations()

        // Check and restore interrupted operations
        if (isCriticalOperationRunning) {
            resumeCriticalOperation()
        }

        // Update UI based on interruption duration
        updateUIAfterInterruption()
    }

    override fun onUserLeaveHint() {
        super.onUserLeaveHint()
        // User pressed Home or Recent Apps button
        saveTemporaryState()
        logInterruptionEvent("user_leave_hint")
    }

    override fun onWindowFocusChanged(hasFocus: Boolean) {
        super.onWindowFocusChanged(hasFocus)

        if (!hasFocus) {
            // App losing focus - save immediate state
            saveImmediateState()
        } else {
            // App regaining focus - check state consistency
            verifyStateConsistency()

            // Measure interruption duration
            val duration = System.currentTimeMillis() - lastFocusLossTime
            if (duration > INTERRUPTION_THRESHOLD) {
                refreshData()
            }
        }
    }

    private fun handleSpecificInterruptions() {
        // Audio focus changes
        val audioManager = getSystemService(Context.AUDIO_SERVICE) as AudioManager
        audioManager.requestAudioFocus(
            { focusChange ->
                when (focusChange) {
                    AudioManager.AUDIOFOCUS_LOSS -> {
                        // Long-term loss - stop playback
                        pauseMediaPlayback()
                    }
                    AudioManager.AUDIOFOCUS_LOSS_TRANSIENT -> {
                        // Short-term interruption - pause
                        pauseMediaPlayback()
                    }
                    AudioManager.AUDIOFOCUS_GAIN -> {
                        // Regained focus - resume if appropriate
                        resumeMediaPlayback()
                    }
                }
            },
            AudioManager.STREAM_MUSIC,
            AudioManager.AUDIOFOCUS_GAIN
        )
    }

    companion object {
        private const val KEY_USER_INPUT = "user_input"
        private const val KEY_PROGRESS = "operation_progress"
        private const val KEY_CRITICAL_OP = "critical_operation"
        private const val KEY_SCROLL_POSITION = "scroll_position"
        private const val INTERRUPTION_THRESHOLD = 30000L // 30 seconds
    }
}

// iOS App Delegate with comprehensive interruption handling
class AppDelegate: UIResponder, UIApplicationDelegate {

    var window: UIWindow?
    private var backgroundTask: UIBackgroundTaskIdentifier = .invalid

    func application(_ application: UIApplication,
                     willFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
        // Enable state restoration
        application.extendStateRestoration()
        return true
    }

    func applicationWillResignActive(_ application: UIApplication) {
        // Interruption is about to begin (call, notification, etc.)

        // Save immediate UI state
        saveImmediateState()

        // Pause ongoing activities
        pauseGamePlay()
        pauseMediaPlayback()

        // Dim or hide sensitive information
        hideSensitiveContent()

        // Start interruption timer
        interruptionStartTime = Date()
    }

    func applicationDidEnterBackground(_ application: UIApplication) {
        // App is entering background

        // Start background task for cleanup
        backgroundTask = application.beginBackgroundTask {
            // Cleanup if time expires
            self.cleanupInterruptedOperations()
            application.endBackgroundTask(self.backgroundTask)
            self.backgroundTask = .invalid
        }

        // Save state to persistent storage
        saveUserData()
        saveAppState()

        // Reduce memory usage
        clearCaches()
        releaseUnnecessaryResources()

        // Schedule background tasks if needed
        scheduleBackgroundRefresh()

        // End background task
        DispatchQueue.global().asyncAfter(deadline: .now() + 25) {
            application.endBackgroundTask(self.backgroundTask)
            self.backgroundTask = .invalid
        }
    }

    func applicationWillEnterForeground(_ application: UIApplication) {
        // App will return to foreground

        // Prepare to resume
        prepareForResume()

        // Check if data needs refresh
        if shouldRefreshData() {
            prepareDataRefresh()
        }

        // Cancel any pending background tasks
        if backgroundTask != .invalid {
            application.endBackgroundTask(backgroundTask)
            backgroundTask = .invalid
        }
    }

    func applicationDidBecomeActive(_ application: UIApplication) {
        // App has become active after interruption

        // Calculate interruption duration
        if let startTime = interruptionStartTime {
            let duration = Date().timeIntervalSince(startTime)
            logInterruptionDuration(duration)

            // Take different actions based on duration
            if duration > 300 { // 5 minutes
                refreshAllData()
            } else if duration > 30 { // 30 seconds
                refreshStaleData()
            }
        }

        // Resume activities
        resumeMediaPlayback()
        restoreUIState()

        // Show sensitive content again
        showSensitiveContent()

        // Reset interruption timer
        interruptionStartTime = nil
    }

    func application(_ application: UIApplication,
                     shouldSaveApplicationState coder: NSCoder) -> Bool {
        return true
    }

    func application(_ application: UIApplication,
                     shouldRestoreApplicationState coder: NSCoder) -> Bool {
        return true
    }

    func application(_ application: UIApplication,
                     willEncodeRestorableStateWith coder: NSCoder) {
        // Encode restoration state
        coder.encode(currentUser, forKey: "currentUser")
        coder.encode(selectedItemId, forKey: "selectedItem")
        coder.encode(scrollPosition, forKey: "scrollPosition")

        // Save view controller hierarchy
        if let rootVC = window?.rootViewController {
            coder.encode(rootVC, forKey: "rootViewController")
        }
    }

    func application(_ application: UIApplication,
                     didDecodeRestorableStateWith coder: NSCoder) {
        // Decode and restore state
        if let user = coder.decodeObject(forKey: "currentUser") as? User {
            currentUser = user
        }

        if let itemId = coder.decodeObject(forKey: "selectedItem") as? String {
            selectedItemId = itemId
        }

        if let position = coder.decodeObject(forKey: "scrollPosition") as? CGFloat {
            scrollPosition = position
        }

        // Restore UI
        restoreUIFromState()
    }

    // Handle specific interruption types
    func handleAudioInterruption(notification: Notification) {
        guard let userInfo = notification.userInfo,
              let typeValue = userInfo[AVAudioSessionInterruptionTypeKey] as? UInt,
              let type = AVAudioSession.InterruptionType(rawValue: typeValue) else {
            return
        }

        switch type {
        case .began:
            // Interruption began
            pauseAudioPlayback()

        case .ended:
            // Interruption ended
            if let optionsValue = userInfo[AVAudioSessionInterruptionOptionKey] as? UInt {
                let options = AVAudioSession.InterruptionOptions(rawValue: optionsValue)
                if options.contains(.shouldResume) {
                    resumeAudioPlayback()
                }
            }
        @unknown default:
            break
        }
    }

    func handleMemoryWarning() {
        // Clear caches
        clearImageCache()
        clearDocumentCache()

        // Save state immediately
        saveCriticalState()

        // Log memory warning
        logMemoryWarningEvent()
    }
}

