// Comprehensive battery optimization for Android
package com.example.app.battery

import android.app.*
import android.content.*
import android.os.*
import android.os.PowerManager
import android.provider.Settings
import androidx.core.app.NotificationCompat
import java.util.concurrent.TimeUnit

/**
 * Battery-aware service manager
 */
class BatteryAwareServiceManager(private val context: Context) {

    private val powerManager = context.getSystemService(Context.POWER_SERVICE) as PowerManager
    private val batteryManager = context.getSystemService(Context.BATTERY_SERVICE) as BatteryManager
    private val alarmManager = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager

    /**
     * Check if battery optimization is enabled for app
     */
    fun isBatteryOptimizationIgnored(): Boolean {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            val packageName = context.packageName
            val intent = Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS).apply {
                data = Uri.parse("package:$packageName")
            }
            context.startActivity(intent)
            false // User needs to grant permission
        } else {
            true // No battery optimization pre-Marshmallow
        }
    }

    /**
     * Check current battery level and charging state
     */
    fun getBatteryInfo(): BatteryInfo {
        val batteryStatus: Intent? = IntentFilter(Intent.ACTION_BATTERY_CHANGED).let { filter ->
            context.registerReceiver(null, filter)
        }

        return batteryStatus?.let { intent ->
            val level = intent.getIntExtra(BatteryManager.EXTRA_LEVEL, -1)
            val scale = intent.getIntExtra(BatteryManager.EXTRA_SCALE, -1)
            val percentage = (level * 100) / scale.toFloat()

            val status = intent.getIntExtra(BatteryManager.EXTRA_STATUS, -1)
            val isCharging = status == BatteryManager.BATTERY_STATUS_CHARGING
                        || status == BatteryManager.BATTERY_STATUS_FULL

            BatteryInfo(
                percentage = percentage,
                isCharging = isCharging,
                batteryHealth = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                    batteryManager.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY)
                } else {
                    100 // Default value
                }
            )
        } ?: BatteryInfo()
    }

    /**
     * Optimize background work based on battery level
     */
    fun scheduleBatteryAwareWork(batteryInfo: BatteryInfo) {
        val workManager = WorkManager.getInstance(context)

        val constraints = Constraints.Builder()
            .setRequiresBatteryNotLow(batteryInfo.percentage > 20)
            .setRequiresCharging(batteryInfo.percentage < 30)
            .build()

        val batteryAwareWork = PeriodicWorkRequestBuilder<BatteryAwareWorker>(
            15, TimeUnit.MINUTES // Reduced frequency during low battery
        )
            .setConstraints(constraints)
            .setBackoffCriteria(
                BackoffPolicy.LINEAR,
                PeriodicWorkRequest.MIN_BACKOFF_MILLIS,
                TimeUnit.MILLISECONDS
            )
            .build()

        workManager.enqueueUniquePeriodicWork(
            "battery_aware_sync",
            ExistingPeriodicWorkPolicy.KEEP,
            batteryAwareWork
        )
    }

    /**
     * Manage wake locks efficiently
     */
    class PowerLockManager {
        private var wakeLock: PowerManager.WakeLock? = null

        fun acquirePartialWakeLock(tag: String, timeoutMs: Long = 30000) {
            val powerManager = context.getSystemService(Context.POWER_SERVICE) as PowerManager
            wakeLock = powerManager.newWakeLock(
                PowerManager.PARTIAL_WAKE_LOCK,
                "$context.packageName:$tag"
            )
            wakeLock?.acquire(timeoutMs)
        }

        fun releaseWakeLock() {
            wakeLock?.let {
                if (it.isHeld) {
                    it.release()
                }
            }
            wakeLock = null
        }

        fun acquireScreenWakeLock() {
            val powerManager = context.getSystemService(Context.POWER_SERVICE) as PowerManager
            wakeLock = powerManager.newWakeLock(
                PowerManager.SCREEN_DIM_WAKE_LOCK or PowerManager.ACQUIRE_CAUSES_WAKEUP,
                "$context.packageName:screen"
            )
            wakeLock?.acquire(10000) // Release after 10 seconds
        }
    }

    /**
     * Optimize network usage for battery
     */
    fun optimizeNetworkUsage() {
        // Use JobScheduler for network operations
        val jobScheduler = context.getSystemService(Context.JOB_SCHEDULER_SERVICE) as JobScheduler

        val networkJob = JobInfo.Builder(1, ComponentName(context, NetworkJobService::class.java))
            .setRequiredNetworkType(JobInfo.NETWORK_TYPE_UNMETERED)
            .setRequiresCharging(true) // Only on charger for large downloads
            .setRequiresBatteryNotLow(true)
            .setPeriodic(TimeUnit.HOURS.toMillis(1)) // Batch network requests
            .build()

        jobScheduler.schedule(networkJob)
    }

    /**
     * Monitor and log battery usage
     */
    class BatteryUsageMonitor {
        private var usageStartTime: Long = 0
        private var initialBatteryLevel: Float = 0f

        fun startMonitoring() {
            usageStartTime = System.currentTimeMillis()
            initialBatteryLevel = getBatteryInfo().percentage
        }

        fun stopMonitoring(): BatteryUsageReport {
            val duration = System.currentTimeMillis() - usageStartTime
            val finalBatteryLevel = getBatteryInfo().percentage
            val batteryDrain = initialBatteryLevel - finalBatteryLevel

            return BatteryUsageReport(
                durationMs = duration,
                batteryDrainPercent = batteryDrain,
                estimatedMah = calculateMahDrain(batteryDrain, duration),
                wakelockCount = getWakeLockStats(),
                networkBytes = getNetworkUsage()
            )
        }

        private fun calculateMahDrain(percentDrain: Float, durationMs: Long): Double {
            // Assuming 4000mAh battery
            val batteryCapacityMah = 4000.0
            return (percentDrain / 100) * batteryCapacityMah
        }
    }
}

/**
 * Battery-aware worker
 */
class BatteryAwareWorker(context: Context, params: WorkerParameters) : Worker(context, params) {
    override fun doWork(): Result {
        return try {
            // Check battery level before proceeding
            val batteryManager = BatteryAwareServiceManager(applicationContext)
            val batteryInfo = batteryManager.getBatteryInfo()

            if (batteryInfo.percentage < 15 && !batteryInfo.isCharging) {
                // Skip non-critical work during low battery
                return Result.success()
            }

            // Perform battery-optimized work
            performOptimizedWork(batteryInfo)

            Result.success()
        } catch (e: Exception) {
            Result.failure()
        }
    }

    private fun performOptimizedWork(batteryInfo: BatteryInfo) {
        // Implementation depends on specific app requirements
    }
}

/**
 * Data classes for battery information
 */
data class BatteryInfo(
    val percentage: Float = 0f,
    val isCharging: Boolean = false,
    val batteryHealth: Int = 100
)

data class BatteryUsageReport(
    val durationMs: Long,
    val batteryDrainPercent: Float,
    val estimatedMah: Double,
    val wakelockCount: Int,
    val networkBytes: Long
)

// Comprehensive battery optimization for iOS
import UIKit
import Foundation
import CoreLocation
import BackgroundTasks
import UserNotifications

/**
 * Battery-aware service manager for iOS
 */
class iOSBatteryManager {

    private let processInfo = ProcessInfo.processInfo
    private let device = UIDevice.current
    private let notificationCenter = UNUserNotificationCenter.current()

    /**
     * Check if low power mode is enabled
     */
    var isLowPowerModeEnabled: Bool {
        return processInfo.isLowPowerModeEnabled
    }

    /**
     * Get current battery level
     */
    var batteryLevel: Float {
        device.isBatteryMonitoringEnabled = true
        return device.batteryLevel
    }

    /**
     * Get battery state
     */
    var batteryState: UIDevice.BatteryState {
        device.isBatteryMonitoringEnabled = true
        return device.batteryState
    }

    /**
     * Schedule battery-aware background tasks
     */
    func scheduleBatteryAwareBackgroundTask() {
        // Register background task
        BGTaskScheduler.shared.register(forTaskWithIdentifier: "com.example.batteryTask",
                                       using: nil) { task in
            self.handleBackgroundTask(task as! BGProcessingTask)
        }

        // Schedule task
        let request = BGProcessingTaskRequest(identifier: "com.example.batteryTask")
        request.requiresNetworkConnectivity = true
        request.requiresExternalPower = batteryLevel < 0.3 // Only on charger if battery low

        do {
            try BGTaskScheduler.shared.submit(request)
            print("Background task scheduled for battery-aware execution")
        } catch {
            print("Failed to schedule background task: \(error)")
        }
    }

    private func handleBackgroundTask(_ task: BGProcessingTask) {
        // Check battery conditions before starting
        if isLowPowerModeEnabled || batteryLevel < 0.2 {
            // Skip or reduce work in low power conditions
            performReducedWork()
        } else {
            // Perform full work
            performFullWork()
        }

        task.setTaskCompleted(success: true)
    }

    /**
     * Optimize location updates for battery
     */
    class BatteryAwareLocationManager: NSObject, CLLocationManagerDelegate {

        private let locationManager = CLLocationManager()
        private var batteryManager: iOSBatteryManager
        private var updateTimer: Timer?

        init(batteryManager: iOSBatteryManager) {
            self.batteryManager = batteryManager
            super.init()

            locationManager.delegate = self
            locationManager.desiredAccuracy = kCLLocationAccuracyHundredMeters
            locationManager.distanceFilter = 50 // Meters
            locationManager.allowsBackgroundLocationUpdates = true
            locationManager.pausesLocationUpdatesAutomatically = true
        }

        func startLocationUpdates() {
            // Adjust accuracy based on battery
            if batteryManager.isLowPowerModeEnabled {
                locationManager.desiredAccuracy = kCLLocationAccuracyKilometer
                locationManager.distanceFilter = 1000 // 1km
            } else if batteryManager.batteryLevel < 0.4 {
                locationManager.desiredAccuracy = kCLLocationAccuracyNearestTenMeters
                locationManager.distanceFilter = 100
            } else {
                locationManager.desiredAccuracy = kCLLocationAccuracyBest
                locationManager.distanceFilter = 10
            }

            locationManager.startUpdatingLocation()

            // Adjust update frequency based on battery
            scheduleAdaptiveUpdates()
        }

        private func scheduleAdaptiveUpdates() {
            updateTimer?.invalidate()

            let interval: TimeInterval
            if batteryManager.isLowPowerModeEnabled {
                interval = 300 // 5 minutes in low power mode
            } else if batteryManager.batteryLevel < 0.3 {
                interval = 180 // 3 minutes
            } else {
                interval = 60 // 1 minute
            }

            updateTimer = Timer.scheduledTimer(withTimeInterval: interval, repeats: true) { _ in
                self.requestLocationUpdate()
            }
        }

        private func requestLocationUpdate() {
            locationManager.requestLocation()
        }

        // MARK: - CLLocationManagerDelegate

        func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
            // Process location updates
            guard let location = locations.last else { return }

            // Log battery-aware location update
            logBatteryAwareLocationUpdate(location)
        }

        func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
            print("Location manager failed: \(error)")
        }

        func locationManagerDidPauseLocationUpdates(_ manager: CLLocationManager) {
            print("Location updates paused to save battery")
        }

        func locationManagerDidResumeLocationUpdates(_ manager: CLLocationManager) {
            print("Location updates resumed")
        }
    }

    /**
     * Optimize network requests for battery
     */
    func scheduleBatteryAwareNetworkRequests() {
        let configuration = URLSessionConfiguration.background(withIdentifier: "com.example.batteryBackground")

        // Configure for battery efficiency
        configuration.isDiscretionary = true // System optimizes timing
        configuration.sessionSendsLaunchEvents = true
        configuration.timeoutIntervalForRequest = 30
        configuration.timeoutIntervalForResource = 600

        if isLowPowerModeEnabled {
            configuration.timeoutIntervalForRequest = 60
            configuration.timeoutIntervalForResource = 1200
        }

        let session = URLSession(configuration: configuration, delegate: nil, delegateQueue: nil)

        // Schedule network tasks based on battery
        scheduleAdaptiveNetworkTasks(session: session)
    }

    private func scheduleAdaptiveNetworkTasks(session: URLSession) {
        // Batch network requests
        let batchSize = isLowPowerModeEnabled ? 5 : 10

        for i in 0..<batchSize {
            let delay = isLowPowerModeEnabled ? Double(i) * 10 : Double(i) * 5

            DispatchQueue.main.asyncAfter(deadline: .now() + delay) {
                self.performBatteryAwareNetworkRequest(session: session)
            }
        }
    }

    /**
     * Monitor and log energy usage
     */
    class EnergyUsageMonitor {
        private var monitoringStartTime: Date?
        private var initialBatteryLevel: Float?
        private var energyUsageLog: [EnergyUsageEntry] = []

        struct EnergyUsageEntry {
            let timestamp: Date
            let activity: String
            let batteryLevel: Float
            let isLowPowerMode: Bool
            let thermalState: ProcessInfo.ThermalState
        }

        func startMonitoring(activity: String) {
            monitoringStartTime = Date()
            initialBatteryLevel = UIDevice.current.batteryLevel

            logEntry(activity: "Start: \(activity)")
        }

        func stopMonitoring(activity: String) -> EnergyUsageReport {
            logEntry(activity: "End: \(activity)")

            guard let startTime = monitoringStartTime,
                  let startBattery = initialBatteryLevel else {
                return EnergyUsageReport()
            }

            let duration = Date().timeIntervalSince(startTime)
            let endBattery = UIDevice.current.batteryLevel
            let batteryDrain = startBattery - endBattery

            return EnergyUsageReport(
                duration: duration,
                batteryDrain: batteryDrain,
                drainPerHour: (batteryDrain / Float(duration)) * 3600,
                entries: energyUsageLog
            )
        }

        private func logEntry(activity: String) {
            let entry = EnergyUsageEntry(
                timestamp: Date(),
                activity: activity,
                batteryLevel: UIDevice.current.batteryLevel,
                isLowPowerMode: ProcessInfo.processInfo.isLowPowerModeEnabled,
                thermalState: ProcessInfo.processInfo.thermalState
            )

            energyUsageLog.append(entry)

            // Persist for analysis
            persistEnergyUsage(entry)
        }

        private func persistEnergyUsage(_ entry: EnergyUsageEntry) {
            // Save to UserDefaults or file for later analysis
            let defaults = UserDefaults.standard
            var history = defaults.array(forKey: "energyUsageHistory") as? [[String: Any]] ?? []

            let dict: [String: Any] = [
                "timestamp": entry.timestamp,
                "activity": entry.activity,
                "batteryLevel": entry.batteryLevel,
                "isLowPowerMode": entry.isLowPowerMode,
                "thermalState": entry.thermalState.rawValue
            ]

            history.append(dict)
            defaults.set(history, forKey: "energyUsageHistory")
        }
    }

    struct EnergyUsageReport {
        let duration: TimeInterval
        let batteryDrain: Float
        let drainPerHour: Float
        let entries: [EnergyUsageEntry]

        init(duration: TimeInterval = 0, batteryDrain: Float = 0, 
             drainPerHour: Float = 0, entries: [EnergyUsageEntry] = []) {
            self.duration = duration
            self.batteryDrain = batteryDrain
            self.drainPerHour = drainPerHour
            self.entries = entries
        }
    }
}

