// iOS Battery Testing with XCTest
import XCTest
import MetricKit

class BatteryConsumptionTests: XCTestCase, MXMetricManagerSubscriber {

    let app = XCUIApplication()
    let device = XCUIDevice.shared
    var energyMonitor: EnergyMonitor!
    var testResults: [TestResult] = []

    struct TestResult {
        let scenario: String
        let duration: TimeInterval
        let batteryDrain: Float
        let cpuUsage: Double
        let networkBytes: Int64
        let timestamp: Date
    }

    class EnergyMonitor {
        private var startBatteryLevel: Float = 0
        private var startTime: Date = Date()
        private var cpuUsageStart: host_cpu_load_info?
        private var networkBytesStart: Int64 = 0

        func startMonitoring() {
            // Enable battery monitoring
            XCUIDevice.shared.isBatteryMonitoringEnabled = true

            // Record initial state
            startBatteryLevel = XCUIDevice.shared.batteryLevel
            startTime = Date()

            // Get initial CPU usage
            cpuUsageStart = getCPULoadInfo()

            // Get initial network usage (simplified)
            networkBytesStart = getNetworkBytesTransferred()

            print("Monitoring started. Battery: \(startBatteryLevel * 100)%")
        }

        func stopMonitoring(scenario: String) -> TestResult {
            let endTime = Date()
            let duration = endTime.timeIntervalSince(startTime)

            let endBatteryLevel = XCUIDevice.shared.batteryLevel
            let batteryDrain = startBatteryLevel - endBatteryLevel

            let cpuUsage = calculateCPUUsage(from: cpuUsageStart)
            let networkBytes = getNetworkBytesTransferred() - networkBytesStart

            return TestResult(
                scenario: scenario,
                duration: duration,
                batteryDrain: batteryDrain,
                cpuUsage: cpuUsage,
                networkBytes: networkBytes,
                timestamp: Date()
            )
        }

        private func getCPULoadInfo() -> host_cpu_load_info? {
            var cpuLoad = host_cpu_load_info()
            var count = mach_msg_type_number_t(MemoryLayout<host_cpu_load_info>.size / MemoryLayout<integer_t>.size)

            let result = withUnsafeMutablePointer(to: &cpuLoad) {
                $0.withMemoryRebound(to: integer_t.self, capacity: Int(count)) {
                    host_statistics(mach_host_self(), HOST_CPU_LOAD_INFO, $0, &count)
                }
            }

            return result == KERN_SUCCESS ? cpuLoad : nil
        }

        private func calculateCPUUsage(from startInfo: host_cpu_load_info?) -> Double {
            guard let startInfo = startInfo,
                  let endInfo = getCPULoadInfo() else {
                return 0.0
            }

            let userDiff = Double(endInfo.cpu_ticks.0 - startInfo.cpu_ticks.0)
            let systemDiff = Double(endInfo.cpu_ticks.1 - startInfo.cpu_ticks.1)
            let idleDiff = Double(endInfo.cpu_ticks.2 - startInfo.cpu_ticks.2)
            let niceDiff = Double(endInfo.cpu_ticks.3 - startInfo.cpu_ticks.3)

            let totalTicks = userDiff + systemDiff + idleDiff + niceDiff

            if totalTicks == 0 {
                return 0.0
            }

            return ((userDiff + systemDiff + niceDiff) / totalTicks) * 100.0
        }

        private func getNetworkBytesTransferred() -> Int64 {
            // Simplified network monitoring
            // In real implementation, use Network framework or system APIs
            return 0
        }
    }

    override func setUp() {
        super.setUp()
        continueAfterFailure = false

        // Enable battery monitoring
        device.isBatteryMonitoringEnabled = true

        // Reset test results
        testResults = []

        // Initialize energy monitor
        energyMonitor = EnergyMonitor()

        // Launch app
        app.launch()

        // Subscribe to MetricKit for detailed metrics
        MXMetricManager.shared.add(self)
    }

    override func tearDown() {
        // Generate test report
        generateTestReport()

        // Clean up
        MXMetricManager.shared.remove(self)
        super.tearDown()
    }

    func testIdleBatteryConsumption() {
        // Scenario: App running in foreground but idle
        energyMonitor.startMonitoring()

        // Wait for 5 minutes
        sleep(300)

        let result = energyMonitor.stopMonitoring(scenario: "Idle")
        testResults.append(result)

        // Assertions
        XCTAssertLessThan(result.batteryDrain, 0.02, // Less than 2% drain in 5 minutes
                         "Idle battery drain too high: \(result.batteryDrain * 100)%")
        XCTAssertLessThan(result.cpuUsage, 5.0, // Less than 5% CPU usage
                         "Idle CPU usage too high: \(result.cpuUsage)%")
    }

    func testVideoPlaybackBatteryConsumption() {
        // Scenario: Video playback
        energyMonitor.startMonitoring()

        // Start video playback
        let playButton = app.buttons["playVideo"]
        XCTAssertTrue(playButton.waitForExistence(timeout: 5))
        playButton.tap()

        // Wait for 10 minutes of playback
        sleep(600)

        let result = energyMonitor.stopMonitoring(scenario: "Video Playback")
        testResults.append(result)

        // Assertions (video playback consumes more battery)
        XCTAssertLessThan(result.batteryDrain, 0.15, // Less than 15% drain in 10 minutes
                         "Video playback battery drain too high: \(result.batteryDrain * 100)%")
    }

    func testNetworkIntensiveBatteryConsumption() {
        // Scenario: Network intensive operations
        energyMonitor.startMonitoring()

        // Start network test
        let networkTestButton = app.buttons["startNetworkTest"]
        XCTAssertTrue(networkTestButton.waitForExistence(timeout: 5))
        networkTestButton.tap()

        // Wait for 5 minutes
        sleep(300)

        let result = energyMonitor.stopMonitoring(scenario: "Network Intensive")
        testResults.append(result)

        // Assertions
        XCTAssertLessThan(result.batteryDrain, 0.10, // Less than 10% drain in 5 minutes
                         "Network battery drain too high: \(result.batteryDrain * 100)%")
    }

    func testBackgroundBatteryConsumption() {
        // Scenario: App in background
        energyMonitor.startMonitoring()

        // Move app to background
        device.press(.home)

        // Wait for 10 minutes
        sleep(600)

        // Bring app back to foreground
        app.activate()

        let result = energyMonitor.stopMonitoring(scenario: "Background")
        testResults.append(result)

        // Assertions - background should have minimal drain
        XCTAssertLessThan(result.batteryDrain, 0.05, // Less than 5% drain in 10 minutes
                         "Background battery drain too high: \(result.batteryDrain * 100)%")
    }

    func testLowPowerModeImpact() {
        // Note: This test requires manual Low Power Mode toggling
        // or special entitlements to simulate programmatically

        // Record baseline in normal mode
        energyMonitor.startMonitoring()
        sleep(300)
        let normalResult = energyMonitor.stopMonitoring(scenario: "Normal Power Mode")
        testResults.append(normalResult)

        // Enable Low Power Mode (requires user action)
        print("Please enable Low Power Mode for this test")
        sleep(10) // Give time to enable

        // Test in Low Power Mode
        energyMonitor.startMonitoring()
        sleep(300)
        let lowPowerResult = energyMonitor.stopMonitoring(scenario: "Low Power Mode")
        testResults.append(lowPowerResult)

        // Low Power Mode should have lower drain
        XCTAssertLessThan(lowPowerResult.batteryDrain, normalResult.batteryDrain,
                         "Low Power Mode should consume less battery")
    }

    // MARK: - MetricKit Integration

    func didReceive(_ payloads: [MXMetricPayload]) {
        for payload in payloads {
            // Log detailed metrics
            if let cpuMetrics = payload.cpuMetrics {
                print("CPU Metrics: \(cpuMetrics)")
            }

            if let batteryMetrics = payload.batteryMetrics {
                print("Battery Metrics: \(batteryMetrics)")
            }

            // Store for analysis
            storeMetricPayload(payload)
        }
    }

    private func storeMetricPayload(_ payload: MXMetricPayload) {
        // Store payload for later analysis
        let defaults = UserDefaults.standard
        var storedPayloads = defaults.array(forKey: "metricPayloads") ?? []

        // Convert to dictionary for storage
        let payloadDict: [String: Any] = [
            "timestamp": payload.timeStampBegin,
            "cpuMetrics": payload.cpuMetrics?.dictionaryRepresentation() ?? [:],
            "batteryMetrics": payload.batteryMetrics?.dictionaryRepresentation() ?? [:]
        ]

        storedPayloads.append(payloadDict)
        defaults.set(storedPayloads, forKey: "metricPayloads")
    }

    // MARK: - Test Reporting

    private func generateTestReport() {
        print("\n=== BATTERY TEST REPORT ===")
        print("Test Date: \(Date())")
        print("Device: \(device.name), Battery Level: \(device.batteryLevel * 100)%")
        print("Low Power Mode: \(ProcessInfo.processInfo.isLowPowerModeEnabled ? "Enabled" : "Disabled")")
        print("\nTest Results:")

        for result in testResults {
            print("""
            Scenario: \(result.scenario)
            Duration: \(String(format: "%.1f", result.duration / 60)) minutes
            Battery Drain: \(String(format: "%.2f", result.batteryDrain * 100))%
            Drain Rate: \(String(format: "%.1f", (result.batteryDrain / Float(result.duration / 3600)) * 100))%/hour
            CPU Usage: \(String(format: "%.1f", result.cpuUsage))%
            """)
        }

        // Save to file
        saveReportToFile()
    }

    private func saveReportToFile() {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyyMMdd_HHmmss"
        let timestamp = formatter.string(from: Date())

        let documentsPath = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        let reportPath = documentsPath.appendingPathComponent("battery_report_\(timestamp).json")

        let reportData: [String: Any] = [
            "timestamp": Date().timeIntervalSince1970,
            "device": device.name,
            "battery_level": device.batteryLevel,
            "low_power_mode": ProcessInfo.processInfo.isLowPowerModeEnabled,
            "results": testResults.map { result in
                return [
                    "scenario": result.scenario,
                    "duration": result.duration,
                    "battery_drain": result.batteryDrain,
                    "cpu_usage": result.cpuUsage,
                    "network_bytes": result.networkBytes
                ]
            }
        ]

        do {
            let jsonData = try JSONSerialization.data(withJSONObject: reportData, options: .prettyPrinted)
            try jsonData.write(to: reportPath)
            print("Report saved to: \(reportPath)")
        } catch {
            print("Failed to save report: \(error)")
        }
    }
}

// Helper extension for MXMetricPayload
private extension MXMetricPayload {
    func dictionaryRepresentation() -> [String: Any] {
        var dict: [String: Any] = ["timestamp": timeStampBegin]

        if let cpu = cpuMetrics {
            dict["cpu"] = [
                "cumulative_cpu_time": cpu.cumulativeCPUTime,
                "average_cpu_time": cpu.averageCPUTime
            ]
        }

        if let battery = batteryMetrics {
            dict["battery"] = [
                "cumulative_background": battery.cumulativeBackgroundTime,
                "cumulative_foreground": battery.cumulativeForegroundTime
            ]
        }

        return dict
    }
}

// Comprehensive battery optimization utilities
package com.example.battery.utils

import android.annotation.SuppressLint
import android.content.Context
import android.net.ConnectivityManager
import android.net.NetworkCapabilities
import android.os.*
import android.util.Log
import androidx.work.*
import java.util.concurrent.TimeUnit

/**
 * Battery optimization utilities for common patterns
 */
object BatteryOptimizationUtils {

    private const val TAG = "BatteryOptimization"

    /**
     * Check if device is charging
     */
    fun isDeviceCharging(context: Context): Boolean {
        val batteryStatus: Intent? = IntentFilter(Intent.ACTION_BATTERY_CHANGED).let { filter ->
            context.registerReceiver(null, filter)
        }

        return batteryStatus?.let { intent ->
            val status = intent.getIntExtra(BatteryManager.EXTRA_STATUS, -1)
            status == BatteryManager.BATTERY_STATUS_CHARGING ||
                    status == BatteryManager.BATTERY_STATUS_FULL
        } ?: false
    }

    /**
     * Check if device is on unmetered network (WiFi)
     */
    @SuppressLint("MissingPermission")
    fun isOnUnmeteredNetwork(context: Context): Boolean {
        val connectivityManager = context.getSystemService(Context.CONNECTIVITY_SERVICE)
                as ConnectivityManager

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            val network = connectivityManager.activeNetwork
            val capabilities = connectivityManager.getNetworkCapabilities(network)

            return capabilities != null &&
                    (capabilities.hasTransport(NetworkCapabilities.TRANSPORT_WIFI) ||
                     capabilities.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET))
        } else {
            @Suppress("DEPRECATION")
            val networkInfo = connectivityManager.activeNetworkInfo
            return networkInfo != null && networkInfo.type == ConnectivityManager.TYPE_WIFI
        }
    }

    /**
     * Schedule battery-aware work
     */
    fun scheduleBatteryAwareWork(
        context: Context,
        workRequest: PeriodicWorkRequest,
        uniqueWorkName: String
    ) {
        val workManager = WorkManager.getInstance(context)

        workManager.enqueueUniquePeriodicWork(
            uniqueWorkName,
            ExistingPeriodicWorkPolicy.KEEP, // Don't schedule duplicate work
            workRequest
        )

        Log.d(TAG, "Scheduled battery-aware work: $uniqueWorkName")
    }

    /**
     * Create battery-optimized work request
     */
    fun createBatteryOptimizedWorkRequest(
        workerClass: Class<out ListenableWorker>,
        repeatInterval: Long = 15, // Default 15 minutes
        flexInterval: Long = 5,    // Flex period 5 minutes
        requiresCharging: Boolean = false,
        requiresBatteryNotLow: Boolean = true,
        requiresStorageNotLow: Boolean = false,
        requiresDeviceIdle: Boolean = false,
        networkType: NetworkType = NetworkType.CONNECTED
    ): PeriodicWorkRequest {
        val constraints = Constraints.Builder()
            .setRequiresCharging(requiresCharging)
            .setRequiresBatteryNotLow(requiresBatteryNotLow)
            .setRequiresStorageNotLow(requiresStorageNotLow)
            .setRequiresDeviceIdle(requiresDeviceIdle)
            .setRequiredNetworkType(networkType)
            .build()

        return PeriodicWorkRequest.Builder(
            workerClass,
            repeatInterval,
            TimeUnit.MINUTES,
            flexInterval,
            TimeUnit.MINUTES
        )
            .setConstraints(constraints)
            .setBackoffCriteria(
                BackoffPolicy.EXPONENTIAL,
                PeriodicWorkRequest.MIN_BACKOFF_MILLIS,
                TimeUnit.MILLISECONDS
            )
            .build()
    }

    /**
     * Debounce function to prevent rapid repeated calls
     */
    class Debouncer(private val delayMillis: Long) {
        private var lastRunTime: Long = 0

        fun shouldExecute(): Boolean {
            val currentTime = System.currentTimeMillis()
            val timeSinceLastRun = currentTime - lastRunTime

            if (timeSinceLastRun >= delayMillis) {
                lastRunTime = currentTime
                return true
            }

            return false
        }

        fun executeIfNeeded(block: () -> Unit) {
            if (shouldExecute()) {
                block()
            }
        }
    }

    /**
     * Battery-aware exponential backoff for retries
     */
    class BatteryAwareBackoff(
        private val context: Context,
        initialDelayMillis: Long = 1000,
        maxDelayMillis: Long = 30000
    ) {
        private var currentDelay = initialDelayMillis
        private val maxDelay = maxDelayMillis

        fun getNextDelay(): Long {
            val delay = currentDelay

            // Adjust delay based on battery conditions
            val adjustedDelay = adjustForBatteryConditions(delay)

            // Exponential increase for next time
            currentDelay = (currentDelay * 2).coerceAtMost(maxDelay)

            return adjustedDelay
        }

        private fun adjustForBatteryConditions(delay: Long): Long {
            val batteryManager = BatteryOptimizationUtils

            return when {
                batteryManager.isDeviceCharging(context) -> {
                    // Faster retries when charging
                    delay.coerceAtMost(5000)
                }
                Build.VERSION.SDK_INT >= Build.VERSION_CODES.M &&
                        context.getSystemService(PowerManager::class.java)
                            ?.isDeviceIdleMode == true -> {
                    // Slower retries in doze mode
                    delay.coerceAtLeast(30000)
                }
                else -> delay
            }
        }

        fun reset() {
            currentDelay = 1000
        }
    }

    /**
     * Batch processor for efficient operations
     */
    class BatchProcessor<T>(
        private val batchSize: Int = 10,
        private val maxWaitTimeMillis: Long = 5000
    ) {
        private val items = mutableListOf<T>()
        private var lastProcessTime: Long = 0
        private var scheduledProcessor: Runnable? = null

        fun addItem(item: T, processor: (List<T>) -> Unit) {
            items.add(item)

            // Process immediately if batch size reached
            if (items.size >= batchSize) {
                processBatch(processor)
                return
            }

            // Schedule delayed processing if first item
            if (items.size == 1) {
                scheduleDelayedProcessing(processor)
            }
        }

        private fun scheduleDelayedProcessing(processor: (List<T>) -> Unit) {
            scheduledProcessor?.let { Handler(Looper.getMainLooper()).removeCallbacks(it) }

            scheduledProcessor = Runnable {
                processBatch(processor)
            }

            Handler(Looper.getMainLooper()).postDelayed(
                scheduledProcessor!!,
                maxWaitTimeMillis
            )
        }

        private fun processBatch(processor: (List<T>) -> Unit) {
            scheduledProcessor?.let { Handler(Looper.getMainLooper()).removeCallbacks(it) }
            scheduledProcessor = null

            if (items.isNotEmpty()) {
                val batch = ArrayList(items)
                items.clear()
                lastProcessTime = System.currentTimeMillis()

                processor(batch)
            }
        }

        fun forceProcess(processor: (List<T>) -> Unit) {
            processBatch(processor)
        }
    }

    /**
     * Monitor and log energy usage patterns
     */
    class EnergyUsageMonitor(private val context: Context) {
        private val usageLog = mutableListOf<EnergyUsageEvent>()

        data class EnergyUsageEvent(
            val timestamp: Long,
            val activity: String,
            val batteryLevel: Int,
            val isCharging: Boolean,
            val networkType: String,
            val durationMs: Long
        )

        fun logActivityStart(activity: String) {
            val event = EnergyUsageEvent(
                timestamp = System.currentTimeMillis(),
                activity = activity,
                batteryLevel = getBatteryLevel(context),
                isCharging = isDeviceCharging(context),
                networkType = getNetworkType(context),
                durationMs = 0
            )

            usageLog.add(event)
            Log.d(TAG, "Activity started: $activity")
        }

        fun logActivityEnd(activity: String) {
            val lastEvent = usageLog.lastOrNull { it.activity == activity }
            lastEvent?.let {
                val duration = System.currentTimeMillis() - it.timestamp

                // Update duration (in real implementation, you'd update the event)
                Log.d(TAG, "Activity ended: $activity, Duration: ${duration}ms")

                // Log energy impact
                logEnergyImpact(activity, duration)
            }
        }

        private fun logEnergyImpact(activity: String, durationMs: Long) {
            // Calculate estimated energy impact
            // This is simplified - in production, use more sophisticated models

            val batteryDrain = estimateBatteryDrain(activity, durationMs)

            Log.i(TAG, """
                Energy Impact Report:
                Activity: $activity
                Duration: ${durationMs}ms
                Estimated Battery Drain: ${String.format("%.3f", batteryDrain)}%
                """.trimIndent())

            // Store for analytics
            storeEnergyAnalytics(activity, durationMs, batteryDrain)
        }

        private fun estimateBatteryDrain(activity: String, durationMs: Long): Double {
            // Simplified estimation model
            // In production, use device-specific power models

            val baseDrainPerHour = when (activity) {
                "VIDEO_PLAYBACK" -> 15.0 // 15%/hour
                "NETWORK_INTENSIVE" -> 10.0 // 10%/hour
                "LOCATION_UPDATES" -> 8.0 // 8%/hour
                "BACKGROUND_SYNC" -> 3.0 // 3%/hour
                else -> 2.0 // 2%/hour for idle
            }

            val durationHours = durationMs / (1000.0 * 60 * 60)
            return baseDrainPerHour * durationHours
        }

        private fun storeEnergyAnalytics(activity: String, durationMs: Long, batteryDrain: Double) {
            val analytics = mapOf(
                "activity" to activity,
                "duration_ms" to durationMs,
                "battery_drain" to batteryDrain,
                "timestamp" to System.currentTimeMillis(),
                "device_model" to Build.MODEL,
                "android_version" to Build.VERSION.SDK_INT
            )

            // Store locally or send to analytics service
            val prefs = context.getSharedPreferences("energy_analytics", Context.MODE_PRIVATE)
            val history = prefs.getStringSet("history", mutableSetOf()) ?: mutableSetOf()
            history.add(analytics.toString())
            prefs.edit().putStringSet("history", history).apply()
        }

        fun generateReport(): String {
            val report = StringBuilder()
            report.append("=== ENERGY USAGE REPORT ===\n")
            report.append("Total activities logged: ${usageLog.size}\n\n")

            // Group by activity type
            val grouped = usageLog.groupBy { it.activity }

            grouped.forEach { (activity, events) ->
                report.append("Activity: $activity\n")
                report.append("  Count: ${events.size}\n")

                if (events.size > 1) {
                    val avgBattery = events.map { it.batteryLevel }.average()
                    report.append("  Average Battery Level: ${String.format("%.1f", avgBattery)}%\n")
                }
                report.append("\n")
            }

            return report.toString()
        }
    }

    // Helper functions
    private fun getBatteryLevel(context: Context): Int {
        val batteryStatus: Intent? = IntentFilter(Intent.ACTION_BATTERY_CHANGED).let { filter ->
            context.registerReceiver(null, filter)
        }

        return batteryStatus?.let { intent ->
            val level = intent.getIntExtra(BatteryManager.EXTRA_LEVEL, -1)
            val scale = intent.getIntExtra(BatteryManager.EXTRA_SCALE, -1)
            (level * 100) / scale
        } ?: 0
    }

    @SuppressLint("MissingPermission")
    private fun getNetworkType(context: Context): String {
        return try {
            val connectivityManager = context.getSystemService(Context.CONNECTIVITY_SERVICE)
                    as ConnectivityManager

            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
                val network = connectivityManager.activeNetwork
                val capabilities = connectivityManager.getNetworkCapabilities(network)

                when {
                    capabilities?.hasTransport(NetworkCapabilities.TRANSPORT_WIFI) == true -> "WIFI"
                    capabilities?.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR) == true -> "CELLULAR"
                    else -> "UNKNOWN"
                }
            } else {
                @Suppress("DEPRECATION")
                val networkInfo = connectivityManager.activeNetworkInfo
                when (networkInfo?.type) {
                    ConnectivityManager.TYPE_WIFI -> "WIFI"
                    ConnectivityManager.TYPE_MOBILE -> "CELLULAR"
                    else -> "UNKNOWN"
                }
            }
        } catch (e: Exception) {
            "UNKNOWN"
        }
    }
}

