/**
 * Test installation scenarios
 */
class InstallationScenarioTests {

    companion object {
        // ADB commands for installation testing
        const val ADB_INSTALL = "adb install"
        const val ADB_UNINSTALL = "adb uninstall"
        const val ADB_INSTALL_DOWNGRADE = "adb install -d"
        const val ADB_INSTALL_TEST_ONLY = "adb install -t"
        const val ADB_INSTALL_ALLOW_TEST = "adb install --allow-test"
    }

    /**
     * Simulate fresh installation test
     */
    fun testFreshInstallation(apkPath: String): Boolean {
        val command = "$ADB_INSTALL $apkPath"
        return executeAdbCommand(command)
    }

    /**
     * Test update installation
     */
    fun testUpdateInstallation(apkPath: String): Boolean {
        val command = "$ADB_INSTALL -r $apkPath"  // -r for replace
        return executeAdbCommand(command)
    }

    /**
     * Test downgrade installation
     */
    fun testDowngradeInstallation(apkPath: String): Boolean {
        val command = "$ADB_INSTALL_DOWNGRADE $apkPath"
        return executeAdbCommand(command)
    }

    /**
     * Test installation with different options
     */
    fun testInstallationWithOptions(
        apkPath: String,
        options: List<String> = emptyList()
    ): Boolean {
        val optionsString = options.joinToString(" ")
        val command = "$ADB_INSTALL $optionsString $apkPath"
        return executeAdbCommand(command)
    }

    /**
     * Execute ADB command and parse result
     */
    private fun executeAdbCommand(command: String): Boolean {
        return try {
            val process = Runtime.getRuntime().exec(command)
            val exitCode = process.waitFor()

            // Read output
            val inputStream = process.inputStream
            val errorStream = process.errorStream

            val output = inputStream.bufferedReader().use { it.readText() }
            val error = errorStream.bufferedReader().use { it.readText() }

            println("Command: $command")
            println("Exit code: $exitCode")
            println("Output: $output")
            if (error.isNotEmpty()) {
                println("Error: $error")
            }

            exitCode == 0 && output.contains("Success")
        } catch (e: Exception) {
            println("Failed to execute ADB command: ${e.message}")
            false
        }
    }

    /**
     * Test installation on specific device
     */
    fun testInstallationOnDevice(apkPath: String, deviceId: String): Boolean {
        val command = "adb -s $deviceId install $apkPath"
        return executeAdbCommand(command)
    }
}

