/**
 * ADB-based uninstallation testing
 */
class AdbUninstallationTests {

    companion object {
        private const val ADB_UNINSTALL = "adb uninstall"
        private const val ADB_UNINSTALL_KEEP_DATA = "adb uninstall -k"
    }

    fun testUninstallation(packageName: String, keepData: Boolean = false): Boolean {
        val command = if (keepData) {
            "$ADB_UNINSTALL_KEEP_DATA $packageName"
        } else {
            "$ADB_UNINSTALL $packageName"
        }

        return executeAdbCommand(command)
    }

    fun testUninstallationWithOptions(packageName: String, options: List<String>): Boolean {
        val optionsString = options.joinToString(" ")
        val command = "$ADB_UNINSTALL $optionsString $packageName"
        return executeAdbCommand(command)
    }

    private fun executeAdbCommand(command: String): Boolean {
        return try {
            val process = Runtime.getRuntime().exec(command)
            val exitCode = process.waitFor()

            val output = process.inputStream.bufferedReader().use { it.readText() }
            val error = process.errorStream.bufferedReader().use { it.readText() }

            println("Command: $command")
            println("Exit code: $exitCode")
            println("Output: $output")
            if (error.isNotEmpty()) {
                println("Error: $error")
            }

            exitCode == 0 && output.contains("Success")
        } catch (e: Exception) {
            println("Failed to execute ADB command: ${e.message}")
            false
        }
    }

    /**
     * Test comprehensive uninstallation scenarios
     */
    fun runUninstallationTestSuite(packageName: String) {
        println("\n=== UNINSTALLATION TEST SUITE ===")
        println("Package: $packageName")

        val testCases = listOf(
            Pair("Normal uninstallation", listOf<String>()),
            Pair("Uninstallation keeping data", listOf("-k")),
            Pair("User 0 uninstallation", listOf("--user", "0"))
        )

        var allTestsPassed = true

        for ((testName, options) in testCases) {
            println("\nTest: $testName")

            // First, ensure app is installed
            // (In real test, you would install it here)

            // Perform uninstallation
            val success = testUninstallationWithOptions(packageName, options)

            if (success) {
                println("✅ $testName: PASSED")

                // Verify app is uninstalled
                val isInstalled = checkIfPackageInstalled(packageName)
                if (isInstalled && options.contains("-k")) {
                    println("Package still installed (data kept) - Expected")
                } else if (!isInstalled && !options.contains("-k")) {
                    println("Package uninstalled - Expected")
                } else {
                    println("⚠️  Unexpected state")
                    allTestsPassed = false
                }
            } else {
                println("❌ $testName: FAILED")
                allTestsPassed = false
            }
        }

        println("\n=== TEST SUITE COMPLETE ===")
        println("Overall result: ${if (allTestsPassed) "PASSED" else "FAILED"}")
    }

    private fun checkIfPackageInstalled(packageName: String): Boolean {
        val command = "adb shell pm list packages $packageName"
        return try {
            val process = Runtime.getRuntime().exec(command)
            val output = process.inputStream.bufferedReader().use { it.readText() }
            output.contains(packageName)
        } catch (e: Exception) {
            false
        }
    }
}

