/**
 * Test FirebaseMessagingService for capturing notifications
 */
class TestFirebaseMessagingService {

    data class DeliveryResult(
        val handled: Boolean = false,
        val shown: Boolean = false,
        val systemShown: Boolean = false
    )

    fun captureNotification(remoteMessage: RemoteMessage): Any? {
        // In real implementation, this would capture and return the notification
        // For testing purposes, return a mock notification object
        return object {
            val messageId = remoteMessage.messageId
            val data = remoteMessage.data
            val from = remoteMessage.from
        }
    }

    fun testDeliveryState(remoteMessage: RemoteMessage, state: String): DeliveryResult {
        // Simulate notification handling for different app states
        return when (state) {
            "App in foreground" -> DeliveryResult(handled = true)
            "App in background" -> DeliveryResult(shown = true)
            "App killed/not running" -> DeliveryResult(systemShown = true)
            "Device in doze mode" -> DeliveryResult(systemShown = true) // System may delay
            "Device with battery optimization" -> DeliveryResult(shown = true)
            else -> DeliveryResult()
        }
    }
}

