        notificationCenter.requestAuthorization(options: [.alert, .sound, .badge]) { granted, error in
            if let error = error {
                print("Notification permission error: \(error)")
            }
            print("Notification permission granted: \(granted)")
            expectation.fulfill()
        }

        waitForExpectations(timeout: 10, handler: nil)
    }

    /**
     * Test notification permission status
     */
    func testNotificationPermissions() {
        let expectation = self.expectation(description: "Check notification settings")

        notificationCenter.getNotificationSettings { settings in
            print("Notification Settings:")
            print("  Authorization Status: \(settings.authorizationStatus)")
            print("  Sound Setting: \(settings.soundSetting)")
            print("  Badge Setting: \(settings.badgeSetting)")
            print("  Alert Setting: \(settings.alertSetting)")
            print("  Notification Center Setting: \(settings.notificationCenterSetting)")
            print("  Lock Screen Setting: \(settings.lockScreenSetting)")

            // For iOS 12+, check provisional and critical alert settings
            if #available(iOS 12.0, *) {
                print("  Provisional: \(settings.provisional)")
