    /**
     * Test local notification delivery
     */
    func testLocalNotificationDelivery() {
        let expectation = self.expectation(description: "Local notification delivered")

        let content = UNMutableNotificationContent()
        content.title = "Test Notification"
        content.body = "This is a test local notification"
        content.sound = .default
        content.badge = 1
        content.userInfo = ["test_id": "local_test_123", "action": "test_action"]

        // Create trigger (immediate)
        let trigger = UNTimeIntervalNotificationTrigger(timeInterval: 1, repeats: false)

        // Create request
        let request = UNNotificationRequest(
            identifier: "test_local_notification",
            content: content,
            trigger: trigger
        )

        // Schedule notification
        notificationCenter.add(request) { error in
            if let error = error {
                XCTFail("Failed to schedule local notification: \(error)")
            } else {
                print("Local notification scheduled successfully")
            }
            expectation.fulfill()
        }

        waitForExpectations(timeout: 5, handler: nil)

        // Wait a bit for notification to fire
        sleep(2)

        // Check if notification was delivered
        checkNotificationDelivery(identifier: "test_local_notification")
    }

    private func checkNotificationDelivery(identifier: String) {
        let expectation = self.expectation(description: "Check delivered notifications")

        notificationCenter.getDeliveredNotifications { notifications in
            let matchingNotifications = notifications.filter { $0.request.identifier == identifier }

            if matchingNotifications.isEmpty {
                print("Warning: Notification not found in delivered notifications")
                // Check pending notifications instead
                self.notificationCenter.getPendingNotificationRequests { requests in
                    let pending = requests.filter { $0.identifier == identifier }
                    print("Pending notifications with ID: \(pending.count)")
                    expectation.fulfill()
                }
            } else {
                print("Notification delivered: \(matchingNotifications.count) found")
                expectation.fulfill()
            }
        }

        waitForExpectations(timeout: 5, handler: nil)
    }

