-- Comprehensive Database Upgrade Validation Script
-- Tests data integrity, schema changes, and performance after upgrade

SET NOCOUNT ON;
GO

-- Create validation log table
IF NOT EXISTS (SELECT * FROM sys.tables WHERE name = 'UpgradeValidationLog')
BEGIN
    CREATE TABLE UpgradeValidationLog (
        LogID INT IDENTITY(1,1) PRIMARY KEY,
        TestCategory NVARCHAR(100),
        TestName NVARCHAR(200),
        TestDescription NVARCHAR(500),
        ExpectedValue SQL_VARIANT,
        ActualValue SQL_VARIANT,
        Status NVARCHAR(20),
        ErrorMessage NVARCHAR(MAX),
        TestTimestamp DATETIME DEFAULT GETDATE(),
        DurationMs INT
    );
    PRINT 'Created UpgradeValidationLog table';
END
GO

-- Procedure to log test results
CREATE OR ALTER PROCEDURE LogTestResult 
    @TestCategory NVARCHAR(100),
    @TestName NVARCHAR(200),
    @TestDescription NVARCHAR(500),
    @ExpectedValue SQL_VARIANT = NULL,
    @ActualValue SQL_VARIANT = NULL,
    @Status NVARCHAR(20),
    @ErrorMessage NVARCHAR(MAX) = NULL,
    @DurationMs INT = NULL
AS
BEGIN
    INSERT INTO UpgradeValidationLog (
        TestCategory, TestName, TestDescription, 
        ExpectedValue, ActualValue, Status, 
        ErrorMessage, TestTimestamp, DurationMs
    ) VALUES (
        @TestCategory, @TestName, @TestDescription,
        @ExpectedValue, @ActualValue, @Status,
        @ErrorMessage, GETDATE(), @DurationMs
    );
END
GO

-- Procedure to run comprehensive upgrade validation
CREATE OR ALTER PROCEDURE ValidateDatabaseUpgrade
    @ExpectedVersion NVARCHAR(50)
AS
BEGIN
    DECLARE @StartTime DATETIME = GETDATE();
    DECLARE @TestStartTime DATETIME;
    DECLARE @RowCount INT;
    DECLARE @TableCount INT;
    DECLARE @ActualVersion NVARCHAR(50);
    DECLARE @ErrorMessage NVARCHAR(MAX);

    BEGIN TRY
        PRINT 'Starting comprehensive database upgrade validation...';

        -- 1. Version Validation
        SET @TestStartTime = GETDATE();
        PRINT '1. Validating database version...';

        -- Get actual database version (implementation depends on your version tracking)
        SELECT @ActualVersion = '2.0.0'; -- Replace with actual version query

        IF @ActualVersion = @ExpectedVersion
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Version',
                @TestName = 'Database Version Check',
                @TestDescription = 'Verify database upgraded to expected version',
                @ExpectedValue = @ExpectedVersion,
                @ActualValue = @ActualVersion,
                @Status = 'PASS',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✓ Version check passed';
        END
        ELSE
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Version',
                @TestName = 'Database Version Check',
                @TestDescription = 'Verify database upgraded to expected version',
                @ExpectedValue = @ExpectedVersion,
                @ActualValue = @ActualVersion,
                @Status = 'FAIL',
                @ErrorMessage = 'Version mismatch',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✗ Version check failed';
        END

        -- 2. Schema Validation
        SET @TestStartTime = GETDATE();
        PRINT '2. Validating schema changes...';

        -- Check for expected new tables
        IF EXISTS (SELECT * FROM sys.tables WHERE name = 'NewFeatureTable')
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Schema',
                @TestName = 'New Table Existence',
                @TestDescription = 'Verify new feature table was created',
                @ExpectedValue = 'Table should exist',
                @ActualValue = 'Table exists',
                @Status = 'PASS',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✓ New table check passed';
        END
        ELSE
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Schema',
                @TestName = 'New Table Existence',
                @TestDescription = 'Verify new feature table was created',
                @ExpectedValue = 'Table should exist',
                @ActualValue = 'Table does not exist',
                @Status = 'FAIL',
                @ErrorMessage = 'New feature table missing',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✗ New table check failed';
        END

        -- Check for expected new columns
        IF EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID('ExistingTable') AND name = 'NewColumn')
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Schema',
                @TestName = 'New Column Existence',
                @TestDescription = 'Verify new column was added to existing table',
                @ExpectedValue = 'Column should exist',
                @ActualValue = 'Column exists',
                @Status = 'PASS',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✓ New column check passed';
        END

        -- 3. Data Integrity Validation
        SET @TestStartTime = GETDATE();
        PRINT '3. Validating data integrity...';

        -- Check row counts for critical tables
        SELECT @RowCount = COUNT(*) FROM Users;

        IF @RowCount > 0
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Data Integrity',
                @TestName = 'User Table Row Count',
                @TestDescription = 'Verify user data was preserved',
                @ExpectedValue = '> 0',
                @ActualValue = @RowCount,
                @Status = 'PASS',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✓ User data integrity check passed';
        END
        ELSE
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Data Integrity',
                @TestName = 'User Table Row Count',
                @TestDescription = 'Verify user data was preserved',
                @ExpectedValue = '> 0',
                @ActualValue = @RowCount,
                @Status = 'FAIL',
                @ErrorMessage = 'User table is empty',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✗ User data integrity check failed';
        END

        -- Check for orphaned records
        SET @TestStartTime = GETDATE();
        SELECT @RowCount = COUNT(*)
        FROM Orders o
        LEFT JOIN Users u ON o.UserID = u.UserID
        WHERE u.UserID IS NULL;

        IF @RowCount = 0
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Data Integrity',
                @TestName = 'Referential Integrity Check',
                @TestDescription = 'Verify no orphaned order records',
                @ExpectedValue = 0,
                @ActualValue = @RowCount,
                @Status = 'PASS',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✓ Referential integrity check passed';
        END
        ELSE
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Data Integrity',
                @TestName = 'Referential Integrity Check',
                @TestDescription = 'Verify no orphaned order records',
                @ExpectedValue = 0,
                @ActualValue = @RowCount,
                @Status = 'FAIL',
                @ErrorMessage = 'Found orphaned order records',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✗ Referential integrity check failed';
        END

        -- 4. Performance Validation
        SET @TestStartTime = GETDATE();
        PRINT '4. Validating performance...';

        -- Test critical query performance
        DECLARE @QueryStartTime DATETIME = GETDATE();

        SELECT COUNT(*) 
        INTO #TempResults
        FROM Orders o
        JOIN Users u ON o.UserID = u.UserID
        WHERE o.OrderDate >= DATEADD(DAY, -30, GETDATE());

        DECLARE @QueryDurationMs INT = DATEDIFF(MILLISECOND, @QueryStartTime, GETDATE());

        -- Performance threshold: 1000ms for this query
        IF @QueryDurationMs < 1000
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Performance',
                @TestName = 'Critical Query Performance',
                @TestDescription = 'Verify orders query performs within threshold',
                @ExpectedValue = '< 1000ms',
                @ActualValue = CAST(@QueryDurationMs AS NVARCHAR(20)) + 'ms',
                @Status = 'PASS',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✓ Performance check passed';
        END
        ELSE
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Performance',
                @TestName = 'Critical Query Performance',
                @TestDescription = 'Verify orders query performs within threshold',
                @ExpectedValue = '< 1000ms',
                @ActualValue = CAST(@QueryDurationMs AS NVARCHAR(20)) + 'ms',
                @Status = 'FAIL',
                @ErrorMessage = 'Query performance degraded',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✗ Performance check failed';
        END

        DROP TABLE #TempResults;

        -- 5. Business Rule Validation
        SET @TestStartTime = GETDATE();
        PRINT '5. Validating business rules...';

        -- Example: Validate that new business rule is enforced
        -- Check that all active users have valid email addresses
        SELECT @RowCount = COUNT(*)
        FROM Users
        WHERE Status = 'Active' 
          AND (Email IS NULL OR Email NOT LIKE '%@%.%');

        IF @RowCount = 0
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Business Rules',
                @TestName = 'Email Validation Rule',
                @TestDescription = 'Verify all active users have valid email addresses',
                @ExpectedValue = 0,
                @ActualValue = @RowCount,
                @Status = 'PASS',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✓ Business rule validation passed';
        END
        ELSE
        BEGIN
            EXEC LogTestResult 
                @TestCategory = 'Business Rules',
                @TestName = 'Email Validation Rule',
                @TestDescription = 'Verify all active users have valid email addresses',
                @ExpectedValue = 0,
                @ActualValue = @RowCount,
                @Status = 'FAIL',
                @ErrorMessage = 'Found users without valid email addresses',
                @DurationMs = DATEDIFF(MILLISECOND, @TestStartTime, GETDATE());
            PRINT '  ✗ Business rule validation failed';
        END

        -- Generate summary report
        PRINT '';
        PRINT 'VALIDATION COMPLETE';
        PRINT '====================';

        SELECT 
            TestCategory,
            COUNT(*) as TotalTests,
            SUM(CASE WHEN Status = 'PASS' THEN 1 ELSE 0 END) as PassedTests,
            SUM(CASE WHEN Status = 'FAIL' THEN 1 ELSE 0 END) as FailedTests
        FROM UpgradeValidationLog
        WHERE TestTimestamp >= @StartTime
        GROUP BY TestCategory
        ORDER BY TestCategory;

        PRINT '';
        PRINT 'Detailed results available in UpgradeValidationLog table';

    END TRY
    BEGIN CATCH
        SET @ErrorMessage = ERROR_MESSAGE();

        EXEC LogTestResult 
            @TestCategory = 'System',
            @TestName = 'Validation Script Execution',
            @TestDescription = 'Overall validation script execution',
            @Status = 'ERROR',
            @ErrorMessage = @ErrorMessage,
            @DurationMs = DATEDIFF(MILLISECOND, @StartTime, GETDATE());

        PRINT 'Validation failed with error: ' + @ErrorMessage;
        THROW;
    END CATCH
END
GO

-- Example execution
PRINT 'Running database upgrade validation...';
EXEC ValidateDatabaseUpgrade @ExpectedVersion = '2.0.0';
GO

-- View detailed results
SELECT 
    TestCategory,
    TestName,
    TestDescription,
    ExpectedValue,
    ActualValue,
    Status,
    ErrorMessage,
    TestTimestamp,
    DurationMs
FROM UpgradeValidationLog
ORDER BY TestTimestamp DESC;
GO

// Simulating the beautiful chaos of actual office collaboration

class OfficeDaySimulator {
    constructor() {
        this.departments = ['Sales', 'Engineering', 'Marketing', 'Support', 'HR'];
        this.meetingRooms = ['Boardroom', 'Conference A', 'Conference B', 'Huddle 1', 'Huddle 2'];
        this.events = [];
        this.conflicts = [];
    }

    // Simulate how real people book meetings
    simulateRealisticBooking(user, room, startTime, duration) {
        const event = {
            user,
            room,
            startTime,
            duration,
            status: 'attempting',
            quirks: []
        };

        // Real human behaviors
        const behaviors = [
            () => {
                // User checks multiple times
                event.quirks.push('checked calendar 3 times before booking');
            },
            () => {
                // User books, then immediately modifies
                event.quirks.push('changed duration after booking');
            },
            () => {
                // User books 'just in case'
                event.quirks.push('blocked room as placeholder');
            },
            () => {
                // User forgets and double-books
                event.quirks.push('forgot about existing meeting');
            }
        ];

        // Add random human quirks
        behaviors.forEach(behavior => {
            if (Math.random() > 0.7) behavior();
        });

        // Check for conflicts (like real systems sometimes miss)
        const conflict = this.findConflict(room, startTime, duration);
        if (conflict) {
            event.status = 'conflict';
            event.conflictWith = conflict.user;
            this.conflicts.push({
                room,
                time: startTime,
                users: [user, conflict.user],
                resolution: this.simulateConflictResolution(user, conflict.user)
            });
        } else {
            event.status = 'booked';
            this.events.push(event);
        }

        return event;
    }

    findConflict(room, startTime, duration) {
        // Simulating race conditions: sometimes conflicts aren't detected immediately
        const conflictDelay = Math.random() > 0.8; // 20% chance of delayed conflict detection

        if (conflictDelay) {
            console.log(`⚠️  System lag: conflict detection delayed for ${room}`);
            return null; // Temporary false negative
        }

        return this.events.find(event => 
            event.room === room &&
            event.status === 'booked' &&
            this.timesOverlap(startTime, duration, event.startTime, event.duration)
        );
    }

    timesOverlap(start1, dur1, start2, dur2) {
        const end1 = start1 + dur1;
        const end2 = start2 + dur2;
        return start1 < end2 && start2 < end1;
    }

    simulateConflictResolution(user1, user2) {
        const resolutions = [
            `${user1} graciously reschedules`, // Collaborative
            `${user2} insists on keeping the room`, // Assertive
            `Both show up and have awkward standoff`, // No resolution
            `They find an empty conference room together`, // Creative solution
            `Manager intervenes and gives room to ${Math.random() > 0.5 ? user1 : user2}` // Escalation
        ];

        return resolutions[Math.floor(Math.random() * resolutions.length)];
    }

    simulateMorningRush() {
        console.log('🌅 SIMULATING OFFICE MORNING RUSH (8:30-9:30 AM)');
        console.log('='.repeat(50));

        const users = [
            'Alex (Sales, impatient)',
            'Jamila (Engineering, methodical)',
            'Marcus (Marketing, last-minute)',
            'Sofia (Support, always early)',
            'David (HR, conflict-averse)'
        ];

        // Simulate 30 minutes of booking activity
        const bookings = [];
        for (let i = 0; i < 20; i++) {
            const user = users[Math.floor(Math.random() * users.length)];
            const room = this.meetingRooms[Math.floor(Math.random() * this.meetingRooms.length)];
            const startTime = 8.5 + Math.random() * 1; // Between 8:30 and 9:30
            const duration = 0.5 + Math.random() * 1.5; // 30 min to 2 hours

            const booking = this.simulateRealisticBooking(user, room, startTime, duration);
            bookings.push(booking);

            const timeStr = this.formatTime(startTime);
            const durationStr = this.formatDuration(duration);

            if (booking.status === 'booked') {
                console.log(`✅ ${timeStr}: ${user} booked ${room} for ${durationStr}`);
                if (booking.quirks.length > 0) {
                    console.log(`   ↳ ${booking.quirks.join(', ')}`);
                }
            } else {
                console.log(`❌ ${timeStr}: ${user} conflicted with ${booking.conflictWith} for ${room}`);
            }
        }

        console.log('\n📊 MORNING RUSH RESULTS:');
        console.log(`Total booking attempts: ${bookings.length}`);
        console.log(`Successful bookings: ${bookings.filter(b => b.status === 'booked').length}`);
        console.log(`Conflicts detected: ${this.conflicts.length}`);

        if (this.conflicts.length > 0) {
            console.log('\n⚡ CONFLICT RESOLUTIONS:');
            this.conflicts.forEach((conflict, i) => {
                console.log(`${i+1}. ${conflict.room} at ${this.formatTime(conflict.time)}:`);
                console.log(`   ${conflict.resolution}`);
            });
        }
    }

    formatTime(hours) {
        const h = Math.floor(hours);
        const m = Math.floor((hours - h) * 60);
        return `${h}:${m.toString().padStart(2, '0')}`;
    }

    formatDuration(hours) {
        const h = Math.floor(hours);
        const m = Math.floor((hours - h) * 60);
        return `${h}h ${m}m`;
    }
}

// Run the simulation
console.log('🏢 WELCOME TO THE DIGITAL OFFICE SIMULATOR');
console.log('Testing how real teams actually use shared resources\n');

const office = new OfficeDaySimulator();
office.simulateMorningRush();

console.log('\n' + '='.repeat(50));
console.log('💡 KEY INSIGHT: It\'s not about preventing conflicts—');
console.log('it\'s about handling them gracefully when they inevitably happen.');
console.log('='.repeat(50));

