        weak_passwords = [
            'password', '123456', 'qwerty', 'letmein',
            'admin', 'welcome', 'password123'
        ]

        failures = []
        for pwd in weak_passwords:
            try:
                response = requests.post(f'{self.base_url}/auth/register', json={
                    'username': f'testuser_{hashlib.md5(pwd.encode()).hexdigest()[:8]}',
                    'email': f'test_{hashlib.md5(pwd.encode()).hexdigest()[:8]}@test.com',
                    'password': pwd
                })

                if response.status_code == 201:
                    failures.append({
                        'password': pwd,
