                    })
            except:
                continue

        return {
            'status': 'failed' if failures else 'passed',
            'weak_passwords_accepted': failures
        }

    def test_brute_force_protection(self):
        """Test brute force attack protection"""
        test_user = 'test_user'

        # Attempt multiple failed logins
        failed_attempts = []
        for i in range(15):  # Should trigger lockout around 5-10 attempts
            response = requests.post(f'{self.base_url}/auth/login', json={
                'username': test_user,
                'password': f'wrong_password_{i}'
            })

            failed_attempts.append({
                'attempt': i + 1,
                'status': response.status_code,
                'message': response.json().get('error', '') if response.ok else ''
            })

            # Check for lockout
            if response.status_code == 429 or 'locked' in response.text.lower():
                lockout_attempt = i + 1
                break
        else:
            lockout_attempt = None

        # Verify lockout occurred
        if lockout_attempt is None:
            return {
                'status': 'failed',
                'reason': 'No brute force protection detected',
                'attempts': failed_attempts
            }

        # Test lockout duration
        response = requests.post(f'{self.base_url}/auth/login', json={
            'username': test_user,
            'password': 'actual_password_here'
        })

        if response.status_code == 429:
